L["Fixed slots and missing-aura reminders are unavailable on Classic. Saved settings are kept; active auras still work."] = "Les emplacements fixes et les rappels d’auras manquantes sont indisponibles sur Classic. Les réglages enregistrés sont conservés ; les auras actives fonctionnent toujours."
L["Show when missing is unavailable on this client. Saved settings are kept; the slot shows when present."] = "« Afficher en cas d'absence » est indisponible sur ce client. Les réglages enregistrés sont conservés ; l’emplacement s’affiche quand l’aura est présente."
L["Reminder clicks are unavailable on Classic"] = "Les clics sur les rappels sont indisponibles sur Classic"
L["Custom enchant reminders are unavailable on Classic. The normal player buff lane still shows weapon enchants."] = "Les rappels d’enchantements personnalisés sont indisponibles sur Classic. La rangée normale des améliorations du joueur affiche toujours les enchantements d’arme."
L["PART 3 - Shape Class Resources with its interactive preview and independent Edit Mode placement."] = "PARTIE 3 - Personnalisez les ressources de classe avec l’aperçu interactif et leur placement indépendant en mode Édition."
L["Place Class Resources independently in Edit Mode."] = "Placez les ressources de classe indépendamment en mode Édition."
L["Independent layouts"] = "Dispositions indépendantes"
L["Place Unitframes and Class Resources independently in Edit Mode."] = "Placez les cadres d’unité et les ressources de classe indépendamment en mode Édition."
L["Texture layers use the unit frame's strata. Use Layer (0-30) to set their order."] = "Les couches de texture utilisent le niveau de superposition du cadre d’unité. Utilisez Couche (0-30) pour définir leur ordre."
L["Shows or hides the bundled MSUF release notes."] = "Affiche ou masque les notes de version fournies avec MSUF."
L["Review or run setup again"] = "Vérifier ou relancer la configuration"
L["Get the essentials right in a few minutes"] = "Configurez l’essentiel en quelques minutes"
L["Resume setup"] = "Reprendre la configuration"
L["Run setup again"] = "Relancer la configuration"
L["Opens a copyable link to the MSUF profile imports on Wago."] = "Ouvre un lien copiable vers les imports de profils MSUF sur Wago."
L["Set up Suite"] = "Configurer Suite"
L["Opens the MSUF Suite setup: profile, modules and UI scaling."] = "Ouvre la configuration de MSUF Suite : profil, modules et échelle de l’interface."
L["Shows the Suite page that switches each optional module on or off."] = "Affiche la page Suite permettant d’activer ou de désactiver chaque module facultatif."
L["%d of %d modules on"] = "%d modules sur %d activés"
L["Selects a pending scale percentage; use Apply to commit it."] = "Présélectionne un pourcentage d’échelle ; utilisez Appliquer pour le valider."
L["QUICK SETUP"] = "CONFIGURATION RAPIDE"
L["~5 min"] = "~5 min"
L["Set the essentials first: placement, frame basics, text, auras, and shared style."] = "Configurez d’abord l’essentiel : placement, cadres, texte, auras et style commun."
L["5.76 and older"] = "5.76 et versions antérieures"
L["Your current profile stays exactly as it is. Take a quick tour of the new controls, then decide what you want to configure."] = "Votre profil actuel reste inchangé. Découvrez rapidement les nouveaux réglages, puis décidez de ce que vous souhaitez configurer."
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Frames > Auras holds the expanded shared styles."] = "La configuration et le style individuel se trouvent désormais dans les menus correspondants des cadres d’unité et de groupe/raid. Cadres > Auras propose les styles communs enrichis."
L["per-frame Aura controls and expanded shared styling in Frames > Auras"] = "réglages d’auras par cadre et styles communs enrichis dans Cadres > Auras"

