    ["Use the Bar settings scope dropdown (left panel, bottom) to choose which unit these settings apply to."] = "Utilisez le menu déroulant de portée des barres (panneau gauche, bas) pour choisir l'unité concernée.",
    ["When scope is set to 'Shared', settings apply globally. Select a unit and enable 'Override shared settings' to customize per unitframe."] = "Lorsque la portée est 'Partagé', les paramètres s'appliquent globalement. Sélectionnez une unité et activez 'Remplacer les paramètres partagés' pour personnaliser par cadre.",
