    ["Heal prediction"] = "Prédiction de soins",
    ["Midnight Simple Unit Frames - Auras 2.0"] = "Midnight Simple Unit Frames - Auras 2.0",
    ["Auras 2.0: Target / Focus / Boss 1-5.\nDefaults show ALL buffs & debuffs. This menu controls a shared layout for these units."] = "Auras 2.0 : Cible / Focus / Boss 1-5.\nPar défaut, tous les buffs et débuffs sont affichés. Ce menu contrôle une disposition partagée pour ces unités.",
    ["MSUF Edit Mode"] = "Mode édition MSUF",
    ["MSUF: Can't toggle Edit Mode in combat."] = "MSUF : Impossible de basculer le mode édition en combat.",
    ["Toggle MSUF Edit Mode (only affects Midnight Simple Unit Frames)."] = "Basculer le mode édition MSUF (n'affecte que Midnight Simple Unit Frames).",
    ["Hide Masque borders"] = "Masquer les bordures Masque",
    ["Hides Masque skin border/backdrop for Auras 2.0 icons (keeps icon + cooldown styling)."] = "Masque les bordures/fonds du skin Masque pour les icônes Auras 2.0 (conserve l'icône + le style de recharge).",
    ["Enable Auras 2.0"] = "Activer Auras 2.0",
    ["Master toggle. When off, no auras are shown for Target/Focus/Boss."] = "Interrupteur principal. Désactivé, aucune aura n'est affichée pour Cible/Focus/Boss.",
    ["Enable filters"] = "Activer les filtres",
    ["Edit filters:"] = "Modifier les filtres :",
    ["|cff9aa0a6No overrides active.|r"] = "|cff9aa0a6Aucun remplacement actif.|r",
    ["Master for all filtering for the selected profile (Shared or a per-unit override). When off, no filtering/highlight is applied."] = "Interrupteur principal pour tout filtrage du profil sélectionné (partagé ou par unité). Désactivé, aucun filtrage/surbrillance n'est appliqué.",
    ["Enable Masque skinning"] = "Activer le skinning Masque",
    ["Skins Auras 2.0 icons with Masque (if installed).\n\nWarning: Highlight borders may look odd with some Masque skins."] = "Applique le skin Masque aux icônes Auras 2.0 (si installé).\n\nAttention : les bordures de surbrillance peuvent sembler étranges avec certains skins Masque.",
    ["Masque is not loaded/ready. Enable/load the Masque addon, then /reload."] = "Masque n'est pas chargé/prêt. Activez/chargez l'addon Masque, puis /reload.",
    ["Override shared filters"] = "Remplacer les filtres partagés",
    ["When off, this unit uses Shared filter settings. When on, it uses its own copy of the filters."] = "Désactivé, cette unité utilise les filtres partagés. Activé, elle utilise sa propre copie des filtres.",
    ["Override shared caps"] = "Remplacer les limites partagées",
    ["When off, this unit uses Shared caps (Max Buffs/Debuffs, Icons per row). When on, it uses its own caps."] = "Désactivé, cette unité utilise les limites partagées (Max Buffs/Débuffs, icônes par ligne). Activé, elle utilise ses propres limites.",
    ["Turns off Override shared filters and caps for all units and reverts them to Shared."] = "Désactive les remplacements de filtres et limites pour toutes les unités et les réinitialise aux paramètres partagés.",
    ["When enabled, placeholder auras can be shown while MSUF Edit Mode is active."] = "Si activé, des auras de remplacement sont affichées lorsque le mode édition MSUF est actif.",
