    ["Highlights your own buffs with a border color (visual only; does not filter)."] = "Surligne vos propres buffs avec une couleur de bordure (visuel uniquement ; ne filtre pas).",
    ["Highlight own debuffs"] = "Surligner mes débuffs",
    ["Highlights your own debuffs with a border color (visual only; does not filter)."] = "Surligne vos propres débuffs avec une couleur de bordure (visuel uniquement ; ne filtre pas).",
    ["Show cooldown swipe"] = "Afficher le balayage de recharge",
    ["Swipe darkens on loss"] = "Le balayage s'assombrit au fil du temps",
    ["When enabled, the cooldown swipe represents elapsed time (darkens as time is lost).\n\nTurn this OFF to keep the default cooldown-style swipe."] = "Si activé, le balayage de recharge représente le temps écoulé (s'assombrit au fil du temps).\n\nDésactivez pour garder le balayage de recharge par défaut.",
    ["Show stack count"] = "Afficher le nombre de cumuls",
    ["Shows stack/application counts (e.g. \"2\") on aura icons. Disable to hide stack numbers."] = "Affiche le nombre de cumuls (ex. \"2\") sur les icônes d'aura. Désactivez pour masquer.",
    ["Show cooldown text"] = "Afficher le texte de recharge",
    ["Shows the countdown numbers on aura icons. Disable to hide cooldown numbers (swipe can remain enabled)."] = "Affiche les chiffres de décompte sur les icônes d'aura. Désactivez pour masquer les chiffres (le balayage peut rester actif).",
    ["Show tooltip"] = "Afficher l'infobulle",
    ["Hide permanent buffs"] = "Masquer les buffs permanents",
    ["Hides buffs with no duration. Debuffs are never hidden by this option.\n\nNote: Target/Focus APIs may still show permanent buffs during combat due to API limitations."] = "Masque les buffs sans durée. Les débuffs ne sont jamais masqués par cette option.\n\nNote : Les API Cible/Focus peuvent toujours afficher des buffs permanents en combat en raison de limitations de l'API.",
