    ["Urgent (<=)"] = "Urgent (<=)",
    ["Include"] = "Inclure",
    ["Use Blizzard timer text (max performance)"] = "Utiliser le texte de minuterie Blizzard (performance max)",
    ["When enabled, Blizzard handles countdown numbers natively in C++.\nDisables timer colors but eliminates all periodic timer CPU overhead.\nFont, size and position are still controlled by MSUF."] = "Si activé, Blizzard gère les chiffres de décompte nativement en C++.\nDésactive les couleurs de minuterie mais élimine la charge CPU périodique.\nLa police, la taille et la position sont toujours contrôlées par MSUF.",
    ["Include boss buffs"] = "Inclure les buffs de boss",
    ["Include boss debuffs"] = "Inclure les débuffs de boss",
    ["Always include dispellable debuffs"] = "Toujours inclure les débuffs dissipables",
    ["Additive: this will NOT hide your normal debuffs."] = "Additif : ceci NE masquera PAS vos débuffs normaux.",
    ["Only show boss auras"] = "Afficher uniquement les auras de boss",
    ["Hard filter: when enabled (and filters are enabled), only auras flagged as boss auras will be shown."] = "Filtre strict : si activé (et les filtres sont actifs), seules les auras marquées comme auras de boss seront affichées.",
    ["Only show IMPORTANT buffs"] = "Afficher uniquement les buffs IMPORTANTS",
