    ["Only show IMPORTANT debuffs"] = "Afficher uniquement les débuffs IMPORTANTS",
    ["Hard filter: when enabled (and filters are enabled), only debuffs in Blizzard\'s curated IMPORTANT list will be shown (e.g. raid mechanics, key defensives, etc.)."] = "Filtre strict : si activé, seuls les débuffs de la liste IMPORTANT de Blizzard seront affichés (ex. mécaniques de raid, défensives clés, etc.).",
