    ["Global Style > Fonts controls shared font settings. Unit pages contain per-unit name, health, and power text position and pattern settings."] = "Style global > Polices contrôle les paramètres de police partagée. Les pages d'unité contiennent, par unité, la position et le modèle des textes de nom, de vie et de ressource.",
    ["Global Style > Fonts has Shared settings plus per-scope font overrides. If Party or Raid uses custom font settings, its Name Shortening can stay enabled even when Shared is off. Select Party/Raid in Fonts or reset the font override."] = "Style global > Polices comporte des paramètres partagés ainsi que des remplacements de polices par portée. Si Groupe ou Raid utilise des paramètres de police personnalisés, son raccourcissement de nom peut rester activé même lorsque Partagé est désactivé. Sélectionnez Groupe/Raid dans Polices ou réinitialisez le remplacement de la police.",
    ["Global absorb styling is in Global Style > Bars > Absorb Display. Group incoming heals are in Group Frames > Health & Text > Heal Prediction."] = "Le style d’absorption globale se trouve dans Style global > Barres > Boucliers et absorptions. Les soins entrants du groupe se trouvent dans Cadres de groupe > Santé et texte > Soins entrants.",
    ["Group frames"] = "Cadres de groupe",
    ["How do I make missing health white in Dark Mode?"] = "Comment puis-je rendre la vie manquante blanche en mode sombre ?",
    ["Limits"] = "Limites",
    ["MSUF Dispel Border / Glow"] = "Bordure/lueur de dissipation MSUF",
    ["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from Unit Auras or Group Frames > Buffs & Debuffs."] = "Le mode édition MSUF déplace les cadres et les barres d'incantation prises en charge. Le placement des icônes d'aura est contrôlé depuis les auras d'unité ou les cadres de groupe > Buffs et debuffs.",
    ["MSUF group frames do not use per-player castbars over the health frame. For MSUF castbar positioning, use MSUF Edit Mode and Global Style > Castbar."] = "Les cadres de groupe MSUF n'utilisent pas de barres d'incantation par joueur sur le cadre de vie. Pour le positionnement de la barre d'incantation MSUF, utilisez le mode édition MSUF et Style global > Barre d'incantation.",
    ["Match width: Essential Cooldowns"] = "Ajuster la largeur : temps de recharge essentiels",
    ["Most shared colors are in Global Style > Colors. Bar texture and border style controls are in Global Style > Bars."] = "La plupart des couleurs partagées se trouvent dans Style global > Couleurs. Les contrôles de texture des barres et de style de bordure se trouvent dans Style global > Barres.",
    ["New character profile"] = "Profil des nouveaux personnages",
    ["Not Now"] = "Pas maintenant",
    ["Okay"] = "D'accord",
    ["One-click setup for a ready-to-use class bar:"] = "Configuration en un clic pour une barre de classe prête à l'emploi :",
    ["Open Class Resources for combo points, holy power, soul shards, chi, maelstrom, essence, runes, stagger, detached power, and alternative mana."] = "Ouvrez Ressources de classe pour les points de combo, la puissance sacrée, les éclats d'âme, le chi, le maelström, l'essence, les runes, le report, la ressource détachée et le mana alternatif.",
    ["Open Class Resources for global class-resource bars. Per-unit detached power options are in the unit page > Power Bar."] = "Ouvrez les ressources de classe pour les barres de ressources de classe globales. Les options de ressource détachée par unité se trouvent sur la page de l'unité > Barre de ressource.",
    ["Open Class Resources. Check Enable, Auto-Hide, class-specific behavior, detached power, and alternative mana settings."] = "Ouvrez Ressources de classe. Vérifiez Activer, Masquer automatiquement, le comportement spécifique à la classe, la ressource détachée et les paramètres de mana alternatif.",
    ["Open Focus Target. Use Frame Basics to enable it; it only appears when Focus is enabled and your focus has a target."] = "Ouvrez Cible de focalisation. Utilisez Bases du cadre pour l’activer ; elle n'apparaît que lorsque le focus est activé et que votre focus a une cible.",
    ["Open Gameplay for crosshair, click-cast, focus/target modifier, mouseover, interaction, and targeting options."] = "Ouvrez Gameplay pour les options de réticule, de sorts au clic, de modificateur focus/cible, de survol de la souris, d'interaction et de ciblage.",
    ["Open Global Style > Bars > Rounded Texture. Use the master toggle for all rounded frame textures, or the separate toggles for unit frames, group frames, power bars, and mouseover highlights."] = "Ouvrez Style global > Barres > Texture arrondie. Utilisez la bascule principale pour toutes les textures de cadre arrondies, ou les bascules séparées pour les cadres d'unité, les cadres de groupe, les barres de ressource et les surbrillances au survol.",
    ["Open Global Style > Bars. Textures & Gradient controls shared bar textures; Frame Outline and Highlight Borders control borders."] = "Ouvrez Style global > Barres. Textures et dégradés contrôlent les textures des barres partagées ; Les options Contour du cadre et Bordures de surbrillance contrôlent les bordures.",
    ["Open Global Style > Castbar > GCD Bar. It controls instant-cast GCD display, time text, spell name, and icon."] = "Ouvrez Style global > Barre d'incantation > Barre GCD. Elle contrôle l'affichage du GCD des sorts instantanés, le texte de durée, le nom du sort et l'icône.",
    ["Open Global Style > Castbar > Name Shortening for castbar spell name shortening, max length, and reserved space."] = "Ouvrez Style global > Barre d'incantation > Raccourcissement du nom pour le raccourcissement du nom du sort de la barre d'incantation, la longueur maximale et l'espace réservé.",
    ["Open Global Style > Castbar and use Empowered Casts for Evoker stage color, stage blink, and blink timing."] = "Ouvrez Style global > Barre d'incantation et utilisez Sorts renforcés pour la couleur des étapes de l'évocateur, le clignotement des étapes et sa durée.",
    ["Open Global Style > Castbar for Focus Kick and Interrupt Ready Indicator. Per-unit castbar interrupt toggles are on each unit page."] = "Ouvrez Style global > Barre d'incantation pour Kick Focus et Indicateur d'interruption prêt. Les bascules d'interruption de la barre d'incantation par unité se trouvent sur chaque page d'unité.",
    ["Open Global Style > Colors for class bar colors and unitframe colors. Group health colors are in Group Frames > Health & Text."] = "Ouvrez Style global > Couleurs pour les couleurs de la barre de classe et les couleurs des cadres d'unité. Les couleurs de vie du groupe se trouvent dans Cadres de groupe > Santé et texte.",
    ["Open Global Style > Colors. Bar Colors and Power Bar Colors control HP/power colors; Class Bar Colors controls class overrides."] = "Ouvrez Style global > Couleurs. Les couleurs des barres et les couleurs des barres de ressource contrôlent les couleurs PV/ressource ; Les couleurs de la barre de classe contrôlent les remplacements de classe.",
    ["Open Global Style > Fonts > Name Shortening for unit names. Castbar spell name shortening is in Global Style > Castbar > Name Shortening."] = "Ouvrez Style global > Polices > Raccourcissement du nom pour les noms d’unités. Le raccourcissement du nom des sorts se fait dans Style global > Barre d'incantation > Raccourcissement du nom.",
    ["Open Global Style > Fonts > Name Shortening. It controls name shortening globally; unit text placement is on each unit page > Text."] = "Ouvrez Style global > Polices > Raccourcissement de nom. Il contrôle le raccourcissement des noms globalement ; Le placement du texte de l'unité se fait sur chaque page de l'unité > Texte.",
    ["Open Global Style > Miscellaneous > Blizzard Frames and use Play sound on Target/Target Lost."] = "Ouvrez Style global > Divers > Cadres Blizzard et utilisez Jouer un son lors du ciblage/perte de cible.",
    ["Open Global Style > Miscellaneous > Blizzard Frames and use Show MSUF minimap icon."] = "Ouvrez Style global > Divers > Cadres Blizzard et utilisez Afficher l'icône MSUF sur la minicarte.",
    ["Open Global Style > Miscellaneous > Language. Translation coverage can also be checked with the /msuf locale command."] = "Ouvrez Style global > Divers > Langue. La couverture de traduction peut également être vérifiée avec la commande /msuf locale.",
    ["Open Global Style > Miscellaneous > Menu behavior for edge snap and related menu behavior."] = "Ouvrez Style global > Divers > Comportement du menu pour l'accrochage aux bords et le comportement du menu associé.",
    ["Open Global Style > Miscellaneous > Range Fade. It controls target, focus, and boss out-of-range fading; group range fade is in Group Frames > Health & Text."] = "Ouvrez Style global > Divers > Atténuation par distance. Elle contrôle l'atténuation hors de portée de la cible, du focus et du boss ; l'atténuation par distance du groupe se trouve dans Cadres de groupe > Santé et texte.",
    ["Open Global Style > Miscellaneous > Unitframe tooltips to control mouseover tooltip behavior."] = "Ouvrez Style global > Divers > Info-bulles des cadres d'unité pour contrôler le comportement des info-bulles au survol de la souris.",
    ["Open the unit page > Frame Basics and use Force Blizzard frame on."] = "Ouvrez la page de l'unité > Bases du cadre et utilisez Forcer le cadre Blizzard.",
    ["Open Global Style > Miscellaneous and use the Range Fade section for affected units, alpha, and portrait fading."] = "Ouvrez Style global > Divers et utilisez la section Atténuation par distance pour les unités concernées, l'opacité et le portrait.",
    ["Open Group Frames > Buffs & Debuffs for raid/party aura handling and Aura Utilities. Unit-frame aura filters are in Unit Auras."] = "Ouvrez Cadres de groupe > Buffs et debuffs pour la gestion des auras de raid/groupe et Utilitaires d'aura. Les filtres d'aura des cadres d'unité sont dans Auras d'unité.",
    ["Open Group Frames > Buffs & Debuffs. Use Buffs, custom buffs, and aura filters to prioritize your own HoTs, externals, and healer buffs."] = "Ouvrez Cadres de groupe > Buffs et debuffs. Utilisez des buffs, des buffs personnalisés et des filtres d'aura pour donner la priorité à vos propres HoTs, externes et buffs de soigneur.",
    ["Open Group Frames > Health & Text > Range Fade. That controls party and raid out-of-range fading."] = "Ouvrez Cadres de groupe > Santé et texte > Atténuation par distance. Cela contrôle l'atténuation hors de portée des groupes et des raids.",
    ["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, heal prediction, dispel overlay, debuff stripe, and range fade."] = "Ouvrez Cadres de groupe > Santé et texte. Il contrôle les couleurs de vie, les barres, la barre de ressource, le texte, les soins entrants, la superposition de dissipation, la bande de débuff et l'atténuation par distance.",
    ["Open Group Frames > Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Ouvrez Cadres de groupe > Indicateurs pour les icônes d'état, rôle/chef/assistant, vérification de disponibilité, lueur du focus et autres indicateurs d'état de cadre de groupe.",
    ["Open Group Frames > Layout and check the solo/player visibility options. That is where MSUF controls whether party-style frames appear when you are alone."] = "Ouvrez Cadres de groupe > Mise en page et vérifiez les options de visibilité solo/joueur. C'est là que MSUF contrôle si les cadres de style groupe apparaissent lorsque vous êtes seul.",
    ["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Health & Text > Power Bar > Smooth fill."] = "Ouvrez Cadres de groupe > Disposition pour le remplissage de vie lisse. Pour les barres de ressource des cadres de groupe, ouvrez Cadres de groupe > Santé et texte > Barre de ressource > Remplissage lisse.",
    ["Open Group Frames > Layout. Check enable/show behavior, player/solo visibility, layout mode, frame scaling, and anchoring."] = "Ouvrez Cadres de groupe > Mise en page. Vérifiez l'activation/affichage, la visibilité joueur/solo, le mode de mise en page, la mise à l'échelle du cadre et l'ancrage.",
    ["Open Group Frames > Layout. General/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Ouvrez Cadres de groupe > Mise en page. Général/Disposition contrôle la largeur, la hauteur, l'espacement, les colonnes et la croissance du cadre ; Mise à l'échelle du cadre contrôle le comportement de mise à l’échelle.",
    ["Open Group Frames > Layout. The General and Sorting sections control player/self visibility and how player units are ordered in group frames."] = "Ouvrez Cadres de groupe > Mise en page. Les sections Général et Tri contrôlent la visibilité du joueur/de soi et la façon dont les unités de joueur sont classées dans les cadres de groupe.",
    ["Open Group Frames > Layout. Use Layout, Frame Scaling, and Anchoring for party/raid position, growth, spacing, size, and anchor behavior."] = "Ouvrez Cadres de groupe > Mise en page. Utilisez la mise en page, la mise à l'échelle du cadre et l'ancrage pour la position, la croissance, l'espacement, la taille et le comportement d'ancrage de groupe/raid.",
    ["Open MSUF again with /msuf. If frame positions are broken, use Dashboard > Reset Positions or the profile/reset tools."] = "Ouvrez à nouveau MSUF avec /msuf. Si les positions du cadre sont cassées, utilisez Tableau de bord > Réinitialiser les positions ou les outils de profil/réinitialisation.",
    ["Open Modules > Style for optional style modules such as portrait decoration and dropdown styling."] = "Ouvrez Modules > Style pour les modules de style facultatifs tels que la décoration de portrait et le style de liste déroulante.",
    ["Open Profiles for active profile, spec auto-switching, import/export strings, legacy imports, and reset options."] = "Ouvrez Profils pour le profil actif, le changement automatique par spécialisation, les chaînes d'import/export, les importations héritées et les options de réinitialisation.",
    ["Open Profiles. Check active profile, spec profiles, import/export, and legacy imports. Large imports may need a reload."] = "Ouvrez les profils. Vérifiez le profil actif, les profils de spécialisation, l'import/export et les importations héritées. Les importations importantes peuvent nécessiter un rechargement.",
    ["Open Target of Target. Use Frame Basics to enable it, Text for labels, and Anchoring/Edit Mode for placement."] = "Ouvrez Cible de la cible. Utilisez Bases du cadre pour l’activer, Texte pour les étiquettes et Ancrage/Mode édition pour le placement.",
    ["Open Unit Auras > Caps & Icons. Lower max buffs/debuffs, rows, icon size, and adjust filters."] = "Ouvrez Auras d’unité > Limites et icônes. Réduisez les buffs max/debuffs, les lignes, la taille des icônes et ajustez les filtres.",
    ["Open Unit Auras > Text Coloring for timer colors and text sizes. Group aura cooldown style is in Group Frames > Buffs & Debuffs > Cooldown Style."] = "Ouvrez Auras d'unité > Coloration du texte pour les couleurs de la minuterie et la taille du texte. Le style de temps de recharge de l'aura de groupe se trouve dans Cadres de groupe > Buffs et affaiblissements > Style de temps de recharge.",
    ["Open Unit Auras and use Display plus Caps & Icons for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Ouvrez Auras d'unité et utilisez Affichage et Limites et icônes pour le placement des auras du cadre d'unité. Les icônes de buff/débuff sont configurées comme une disposition d'aura et ne sont pas déplacées via le mode d'édition MSUF.",
    ["Open Unit Auras for unit-frame aura icon sizing and filters. For group frames, use Group Frames > Buffs & Debuffs and custom buff/debuff controls."] = "Ouvrez Auras d'unité pour la taille et les filtres des icônes d'aura des cadres d'unité. Pour les cadres de groupe, utilisez Cadres de groupe > Buffs & Debuffs et les contrôles buff/debuff personnalisés.",
    ["Open Unit Auras for unit-frame debuff filtering. For party/raid dispels, use Group Frames > Indicators and Group Frames > Buffs & Debuffs."] = "Ouvrez Auras d'unité pour le filtrage des débuffs des cadres d’unité. Pour les dissipations de groupe/raid, utilisez Cadres de groupe > Indicateurs et Cadres de groupe > Buffs et debuffs.",
    ["Open Unit Auras, select Player, enable Custom caps, then set Caps & Icons > Max Buffs to 0. Show Buffs is a shared master toggle, so it is locked outside Shared."] = "Ouvrez Auras d'unité, sélectionnez Joueur, activez Limites personnalisées, puis réglez Limites et icônes > Buffs max. sur 0. Afficher les buffs est un interrupteur principal partagé, il est donc verrouillé en dehors de Partagé.",
    ["Open Unit Auras. Check Display, Aura Filters & Sorting, Only Mine, boss aura filters, dispellable filters, and icon caps."] = "Ouvrez Auras d’unité. Vérifiez Affichage, Filtres et tri d'aura, Uniquement les miens, les filtres d'aura de boss, les filtres dissipables et les limites d'icônes.",
    ["Open that unit page and use Frame Basics > Enable. Boss frames also have Boss Layout options."] = "Ouvrez la page de cette unité et utilisez Bases du cadre > Activer. Les cadres de boss ont aussi des options de disposition des boss.",
    ["Open that unit page and use Frame Basics for width, height, and scale. Text size is in Global Style > Fonts or the unit Text section."] = "Ouvrez cette page d'unité et utilisez Bases du cadre pour la largeur, la hauteur et l'échelle. La taille du texte se trouve dans Style global > Polices ou dans la section Texte de l'unité.",
    ["Open the matching unit page and use Load Conditions to control when player, target, focus, boss, or pet frames are shown."] = "Ouvrez la page de l'unité correspondante et utilisez les conditions de chargement pour contrôler le moment où les cadres du joueur, de la cible, du focus, du boss ou du familier sont affichés.",
    ["Open the unit page > Castbar to enable that unit's castbar. Shared castbar visuals are in Global Style > Castbar."] = "Ouvrez la page de l'unité > Barre d'incantation pour activer la barre d'incantation de cette unité. Les visuels partagés se trouvent dans Style global > Barre d'incantation.",
    ["Open the unit page > Status icons. Select Level in Indicator, then use Enabled, Anchor, X/Y Offset, Size, and Layer."] = "Ouvrez la page de l'unité > Icônes d'état. Sélectionnez Niveau dans Indicateur, puis utilisez Activé, Ancre, Décalage X/Y, Taille et Calque.",
    ["Open the unit page > Text. Adjust anchors, offsets, font size, spacing, split spacing, and layer."] = "Ouvrez la page de l'unité > Texte. Ajustez les ancres, les décalages, la taille de la police, l'espacement, l'espacement divisé et l'ordre des calques.",
    ["Open the unit page > Transparency for in-combat/out-of-combat alpha. By default the sliders fade the whole frame; Keep text + portrait visible switches them to the selected layer: Bars, HP Bar, or Backdrop. Group frame transparency is in Group Frames > Layout > Transparency."] = "Ouvrez la page de l'unité > Transparence pour l'opacité en combat/hors combat. Par défaut, les curseurs atténuent l'ensemble du cadre ; Garder le texte + le portrait visibles les fait passer au calque sélectionné : Barres, Barre HP ou Toile de fond. La transparence du cadre de groupe se trouve dans Cadres de groupe > Mise en page > Transparence.",
    ["Open the unit page, then use Frame Basics > Smooth fill for the health bar. For that unit's power bar animation, open Power Bar > Smooth fill."] = "Ouvrez la page de l'unité, puis utilisez Bases du cadre > Remplissage lisse pour la barre de vie. Pour l’animation de la barre de ressource de cette unité, ouvrez Barre de ressource > Remplissage lisse.",
    ["Open the unit page, then use the Portrait section for mode, render type, shape, size, offset, and border."] = "Ouvrez la page de l'unité, puis utilisez la section Portrait pour le mode, le type de rendu, la forme, la taille, le décalage et la bordure.",
    ["Opens: Boss > Frame Basics / Boss Layout"] = "Ouvre : Boss > Bases du cadre / Disposition du boss",
