    ["Opens: Global Style > Colors > Bar Background Tint > Preserve HP color on all unit frames"] = "Ouvre : Style global > Couleurs > Teinte d'arrière-plan de la barre > Conserver la couleur HP sur tous les cadres de l'unité.",
    ["Opens: Global Style > Colors > Bar Colors"] = "Ouvre : Style global > Couleurs > Couleurs des barres",
