    ["Opens: Unit Auras > Caps & Icons"] = "Ouvre : Auras d'unité > Limites et icônes",
    ["Opens: Unit Auras > Display"] = "Ouvre : Auras d'unité > Affichage",
    ["Opens: Unit Auras > Player > Custom caps > Caps & Icons > Max Buffs"] = "Ouvre : Auras d'unité > Joueur > Limites personnalisées > Limites et icônes > Buffs max.",
    ["Opens: Unit Auras > Text Coloring"] = "Ouvre : Auras d'unité > Coloration du texte",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "Disposition des cadres de groupe, de raid et de raid mythique, barres, auras, indicateurs, remplacements de portée et positions",
    ["Positions class bar ABOVE Essential Cooldowns"] = "Place la barre de classe AU-DESSUS des temps de recharge essentiels",
    ["Preserve HP color on all unit frames"] = "Préserver la couleur HP sur tous les cadres de l'unité",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "L'aperçu suit les paramètres actuels de visibilité, d'icône, de texte et de couleur globale de la barre d'incantation.",
    ["Profile actions"] = "Actions de profil",
    ["Quick Setup: Detached Class Bar"] = "Configuration rapide : barre de classe détachée",
    ["Reload"] = "Recharger",
    ["Rows"] = "Lignes",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "Même réglage que chaque page de l'unité > Transparence. Il utilise cette même couleur de piste HP ; désactivé ici signifie qu'au moins un cadre d'unité est désactivé.",
    ["Secret aura (name/fingerprint matched)"] = "Aura secrète (reconnue par nom/empreinte)",
    ["Select:"] = "Sélectionnez :",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "Définissez la teinte d'arrière-plan de la barre sur blanc et activez la couleur personnalisée en mode sombre. S'il est noir, activez Conserver la couleur HP sur tous les cadres de l'unité.",
    ["Setup Now"] = "Configurer maintenant",
    ["Slot"] = "Emplacement",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "Certaines modifications de mise en page reconstruisent les cadres, tandis que les modifications visuelles s'appliquent instantanément. Si nécessaire, fermez et rouvrez le menu ou rechargez après des modifications importantes du profil/import.",
    ["Syncs & anchors power bar to class resources"] = "Synchronise et ancre la barre de ressource aux ressources de classe",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "Le profil actif est enregistré par personnage. Les nouveaux personnages démarrent avec ce profil au lieu de Default.",
    ["This layer is off in settings and cannot be shown in preview."] = "Ce calque est désactivé dans les paramètres et ne peut pas être affiché en aperçu.",
    ["Type a name here before creating or copying a profile."] = "Tapez un nom ici avant de créer ou de copier un profil.",
    ["Undo"] = "Annuler",
    ["Unit Frame Preview"] = "Aperçu du cadre de l'unité",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Les icônes d’état du cadre d’unité se trouvent sur chaque page d’unité. Les indicateurs du cadre de groupe se trouvent dans Cadres de groupe > Indicateurs.",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Utilisez /msuf pour ouvrir MSUF2. Le tableau de bord contient également des outils de réinitialisation, de support, de profil et de mise à l'échelle.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Utilisez Style global > Barres pour les bordures de surbrillance et Cadres de groupe > Indicateurs pour les indicateurs de rôle, de menace, de dissipation, de sort, de coin et de marqueur de raid.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Utilisez Cadres de groupe > Disposition pour la taille et l'espacement, les buffs et debuffs pour l'encombrement de l'aura et les indicateurs pour les icônes d'état à position fixe.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Utilisez les pages Cadres de groupe : mise en page pour la taille/growth/sorting, Santé et texte pour les barres/text, Buffs et debuffs pour les auras et Indicateurs pour les icônes d'état.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Utilisez le mode d'édition MSUF pour faire glisser un seul cadre d'unité. Utilisez la page de l'unité > Ancrage lorsque vous avez besoin de cibles d'ancrage exactes ou de valeurs X/Y.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Utilisez le mode d'édition MSUF pour faire glisser les barres d'incantation prises en charge. Les options d'activation/icône/texte par unité se trouvent sur chaque page d'unité ; le style partagé se trouve dans Style global > Barre d'incantation.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Utilisez le mode d'édition MSUF pour faire glisser le cadre du joueur. Pour obtenir des valeurs d'ancrage ou X/Y exactes, ouvrez ensuite Joueur > Ancrage.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Utilisez les commandes d'échelle du tableau de bord pour l'échelle de menu ou l'échelle UI. Vous pouvez également redimensionner la fenêtre MSUF2 depuis son coin.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Utilisez la page d'unité pour les bascules de barre d'incantation par unité et Style global > Barre d'incantation pour les textures partagées, la direction, GCD, le texte et les options d'interruption.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Utilisez-le si l'estompage de la barre PV fait disparaître la zone de vie vide ou la rend noire. Il conserve la même couleur de piste PV que dans Couleurs.",
    ["Value:"] = "Valeur :",
    ["View"] = "Voir",
    ["Welcome to Class Resources!"] = "Bienvenue dans les ressources de classe !",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW bloque certains changements de cadre protégés en combat. Quittez le combat, puis appliquez les modifications de disposition, d'ancrage, d'activation/désactivation, de profil ou de cadre protégé.",
    ["bottom"] = "en bas",
    ["change background color unit frames"] = "changer la couleur de fond des cadres d'unité",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "disposition des ressources de classe, comportement, style, masquage automatique, barre de ressource détachée et paramètres de mana alternatifs",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "cliquez sur les calques pour masquer - faites glisser les éléments d'aperçu - les flèches déplacent la sélection",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "couleurs du cadre, couleurs de classe/PNJ, couleurs de ressource, couleurs de la barre d'incantation, couleurs de l'aura et paramètres de couleur du gameplay",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "paramètres d'amélioration du gameplay tels que le texte de combat, le réticule et le comportement des sorts au clic",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "comportement global de la barre d'incantation, textures, GCD, paramètres de la barre d'incantation du boss et de l'indicateur d'interruption",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "Comportement de la langue/du menu, rythme de mise à jour, info-bulles, gestion des cadres Blizzard, icône de la minicarte, sons et paramètres d'atténuation par distance.",
    ["none"] = "aucun",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "paramètres de style/module facultatifs tels que le style MSUF et le style déroulant",
    ["scope disabled"] = "portée désactivée",
    ["shared"] = "partagé",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "textures de barre partagées, dégradés, coins de cadre arrondis, affichage d'absorption, contours, bordures de surbrillance, lissage des ressources et tous les remplacements de barres par unité/groupe",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "famille de polices partagée, style de texte, coloration du texte de nom/ressource, raccourcissement du nom et tous les remplacements de polices par unité/groupe",
    ["the entire active profile"] = "tout le profil actif",
    ["uf_target"] = "uf_target",
    ["–"] = "–",
}
for k, v in pairs(MSUF_LOCALE_COVERAGE_frFR) do
    if L[k] == nil or L[k] == k then L[k] = v end
end

L["|cffffd700MSUF:|r Group Frames reset to defaults."] = "|cffffd700MSUF:|r Cadres de groupe réinitialisés par défaut."
L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r Préserver la couleur PV utilise la même couleur de piste PV depuis Couleurs, mais certaines textures de barre peuvent sembler différentes."
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "Cliquez sur une poignée pour sélectionner - faites glisser les calques personnalisés - les flèches déplacent la sélection ; Blizzard est verrouillé"
L["Copy categories"] = "Catégories à copier"
L["Copy Selected"] = "Copier la sélection"
L["Custom Anchor Frame"] = "Cadre d'ancre personnalisé"
L["Custom anchor target (mouse picker)"] = "Cible d'ancre personnalisée (sélecteur souris)"
L["Don't show again"] = "Ne plus afficher"
L["Frame disabled"] = "Cadre désactivé"
L["Growth Direction"] = "Direction de croissance"
L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "Préserver la couleur PV conserve la couleur de remplissage PV pendant que le fondu de calque est actif et dessine la santé manquante séparément avec la même couleur de piste PV depuis Couleurs.\n\nCela peut aider lorsque le fondu de la barre PV fait disparaître la zone vide ou la rend noire. Certaines textures personnalisées peuvent encore sembler plates, sombres ou différentes avec cette option activée."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "Réinitialiser %s par défaut ?\n\nCela réinitialise %s pour le profil actif. Les valeurs par défaut sont lues depuis le profil d'usine MSUF actuel, donc les futures modifications par défaut seront utilisées automatiquement."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "Réinitialiser %s par défaut ?\n\nCela réinitialise tout le profil actif '%s' aux valeurs d'usine MSUF actuelles. Tous les menus de ce profil seront affectés."
L["Reset Scopes"] = "Réinitialiser les portées"

