L["                   Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "                   La confirmation prépare la réinitialisation ; rechargez avec /reload ou utilisez Menu MSUF > Avancé > Réinitialisation d'usine."
L["  !msuf help      - Print this help via chat (from your own character)."] = "  !msuf help      - Affiche cette aide dans le chat (depuis votre propre personnage)."
L["  (then /reload OR MSUF Menu > Advanced > Factory Reset)"] = "  (puis /reload OU Menu MSUF > Avancé > Réinitialisation d'usine)"
L["  /msuf absorb    - Toggle showing total absorb amount in HP text."] = "  /msuf absorb    - Affiche ou masque l'absorption totale dans le texte de vie."
L["  /msuf analytics off|on|status - Toggle Wago Analytics beta telemetry."] = "  /msuf analytics off|on|status - Contrôle la télémétrie bêta de Wago Analytics."
L["  /msuf fullreset - FULL factory reset (all profiles/settings)."] = "  /msuf fullreset - Réinitialisation d'usine COMPLÈTE (tous les profils/réglages)."
L["  /msuf gfhoverdebug on|off|status - Debug group-frame hover + tooltip paths."] = "  /msuf gfhoverdebug on|off|status - Débogue le survol des cadres de groupe et les chemins d'infobulle."
L["  /msuf help      - Show this help."] = "  /msuf help      - Affiche cette aide."
L["  /msuf reset     - Reset all MSUF frame positions and visibility to defaults."] = "  /msuf reset     - Réinitialise les positions et la visibilité de tous les cadres MSUF."
L["  /msufdbgpos     - Toggle position drift debugger (overlay + chat log)."] = "  /msufdbgpos     - Active le débogueur de dérive de position (superposition + journal de chat)."
L["  /rl             - Reload the UI."] = "  /rl             - Recharge l'interface."
