L["|cffff0000MSUF WARNING:|r This will delete |cffff0000ALL|r MSUF profiles & settings for this account."] = "|cffff0000AVERTISSEMENT MSUF :|r Cela supprimera |cffff0000TOUS|r les profils et réglages MSUF de ce compte."
