L["|cffff0000MSUF:|r FULL RESET executed - all MSUF profiles & settings deleted for this account."] = "|cffff0000MSUF :|r RÉINITIALISATION COMPLÈTE effectuée - tous les profils et réglages MSUF de ce compte ont été supprimés."
L["|cffff0000MSUF:|r Usage: /msuf gfhoverdebug on|off|status"] = "|cffff0000MSUF :|r Utilisation : /msuf gfhoverdebug on|off|status"
L["|cffff5555MSUF|r: Can't reload UI in combat. Leave combat, then type /reload."] = "|cffff5555MSUF|r : impossible de recharger l'interface en combat. Quittez le combat, puis tapez /reload."
L["|cffff6060CTRL required:|r |cffffffffhold |r|cff55ff55CTRL + Left-Click|r|cffffffff to confirm the anchor target.|r"] = "|cffff6060CTRL requis :|r |cffffffffmaintenez |r|cff55ff55CTRL + clic gauche|r|cffffffff pour confirmer la cible d'ancrage.|r"
