L["|cffffcc00MSUF:|r Then click: MSUF Menu > Advanced > Factory Reset (or type /reload)."] = "|cffffcc00MSUF :|r Cliquez ensuite : Menu MSUF > Avancé > Réinitialisation d'usine (ou tapez /reload)."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf fullreset confirm|r to stage the reset."] = "|cffffcc00MSUF :|r Tapez |cffffff00/msuf fullreset confirm|r pour préparer la réinitialisation."
L["|cffffcc33No named frame found under cursor.|r |cffffffffTry a different spot.|r"] = "|cffffcc33Aucun cadre nommé sous le curseur.|r |cffffffffEssayez un autre endroit.|r"
L["|cffffd700MSUF:|r Castbar Edit Mode |cff00ff00ON|r drag player/target/focus castbars with the mouse."] = "|cffffd700MSUF :|r Mode d'édition des barres d'incantation |cff00ff00ACTIF|r : déplacez les barres joueur/cible/focalisation à la souris."
L["|cffffd700MSUF:|r Castbar Edit Mode |cffff0000OFF|r."] = "|cffffd700MSUF :|r Mode d'édition des barres d'incantation |cffff0000INACTIF|r."
L["|cffffd700MSUF:|r Rounded frame texture changed. Reload the UI with /reload."] = "|cffffd700MSUF :|r La texture de cadre arrondi a changé. Rechargez l'interface avec /reload."
L["|cffffd700MSUF:|r Use /msuf to open the menu."] = "|cffffd700MSUF :|r Utilisez /msuf pour ouvrir le menu."
L["|cffffff00MSUF:|r Reloading UI to rebuild clean defaults..."] = "|cffffff00MSUF :|r Rechargement de l'interface pour reconstruire des valeurs par défaut propres..."
L["|cffffff00MSUF:|r Reset staged. Please type |cff00ff00/reload|r OR use: MSUF Menu > Advanced > Factory Reset."] = "|cffffff00MSUF :|r Réinitialisation préparée. Tapez |cff00ff00/reload|r OU utilisez Menu MSUF > Avancé > Réinitialisation d'usine."
L["|cffffffffHover a frame, then hold |r|cff55ff55CTRL + Left-Click|r|cffffffff to anchor.  |  Right-Click or Escape cancels.|r"] = "|cffffffffSurvolez un cadre, puis maintenez |r|cff55ff55CTRL + clic gauche|r|cffffffff pour l'ancrer.  |  Clic droit ou Échap annule.|r"
L["|cffffffffLeft Click:|r Open MSUF"] = "|cffffffffClic gauche :|r Ouvrir MSUF"
