L["Added and refined the Menu2 search module."] = "Module de recherche Menu2 ajouté et affiné."
L["Added backend compatibility hardening across MSUF modules."] = "Renforcement de compatibilité backend ajouté aux modules MSUF."
L["Added centralized font registry support for the unit frame runtime."] = "Support d'un registre centralisé de polices ajouté à la runtime des cadres d'unité."
L["Added class-colored bar background support across unit and group frames."] = "Support du fond de barre couleur de classe ajouté aux cadres d'unité et de groupe."
L["Added core swap recolor runtime support."] = "Support runtime du recolor core swap ajouté."
L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Ajout du cadre Cible de focalisation dans les réglages d'unité, le mode édition, les aperçus, les cibles de copie, les options de texte, les icônes et les rafraîchissements runtime."
L["Added improved on/off switch visuals."] = "Visuels d'interrupteur on/off améliorés."
