L["Added new Menu2 search module and improved search/guidance text."] = "Nouveau module de recherche Menu2 ajouté et textes de recherche/guidage améliorés."
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "Nouveaux assets UI/média ajoutés pour interrupteurs et visuels arrondis/superellipse."
L["Added raid group number display next to unit names."] = "Affichage du numéro de groupe de raid ajouté près des noms d'unité."
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "Disposition de cartes Menu2 redessinée pour les pages unité, groupe, aura, indicateur, barres et avancé."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "Ajout des cadres arrondis avec contrôles par surface pour cadres d'unité, cadres de groupe, barres, surbrillances, overlays, absorptions et indicateurs."
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "Médias de masque arrondi ajoutés pour les cadres live et l'aperçu Menu2."
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "Contrôles Texture arrondie ajoutés sous Style global > Barres avec interrupteurs par surface, recherche, localisation, aperçu et demande de rechargement."
