L["Blizzard controls this aura block, so MSUF cannot drag it. Switch to MSUF Custom mode if you want full positioning control. The preview marks the Blizzard-owned area."] = "Blizzard contrôle ce bloc d'auras, MSUF ne peut donc pas le déplacer. Passez en mode MSUF personnalisé pour contrôler entièrement la position. L'aperçu marque la zone gérée par Blizzard."
L["Blizzard locked"] = "Verrouillé par Blizzard"
L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "Le mode Blizzard laisse WoW placer les types d'aura sélectionnés. Le mode MSUF personnalisé permet à MSUF de contrôler taille, croissance, position, filtres et style. La lueur de dissipation est indisponible seulement pour les portées de cadres de groupe où Blizzard contrôle la couche d'auras."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "Blizzard affiche le texte de recharge et de cumul pour les buffs et débuffs natifs. Ces champs de superposition de texte n'affectent que les icônes personnalisées."
