L["This group scope follows Shared name shortening. Turn on custom settings above only when group names need different truncation."] = "Cette portée de groupe suit le raccourcissement partagé. Activez les réglages personnalisés ci-dessus seulement si les noms de groupe doivent être tronqués différemment."
