L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "Les catégories cochées masquent uniquement les icônes d'affaiblissement personnalisées de MSUF. Les affaiblissements affichés par Blizzard ignorent cette liste tant que Utiliser Blizzard : débuffs est activé."
