L["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, dispel overlay, debuff stripe, and range fade. Heal prediction is in Global Style > Bars > Absorb Display."] = "Ouvrez Cadres de groupe > Vie et texte. Cette page contrôle les couleurs de vie, les barres, la barre de ressource, le texte, l'overlay de dissipation, la bande d'affaiblissements et le fondu de portée. La prédiction des soins est dans Style global > Barres > Boucliers et absorptions."
L["Open Unit Auras > Global Ignore List. It can hide predefined aura categories for all unit frames, or per unit after enabling Override for this unit. MSUF does not currently have an ElvUI-style freeform spell-ID blacklist for arbitrary debuffs."] = "Ouvrez Auras d'unité > Liste d'ignorés globale. Elle peut masquer des catégories d'auras prédéfinies pour tous les cadres d'unité, ou par unité après avoir activé Remplacer pour cette unité. MSUF n'a pas actuellement de liste noire libre d'ID de sort façon ElvUI pour des affaiblissements arbitraires."
L["Open this section to enable or disable rounded frame textures and its per-surface toggles."] = "Ouvre cette section pour activer ou désactiver les textures de cadre arrondi et leurs interrupteurs par surface."
L["Opens: Unit Auras > Global Ignore List"] = "Ouvre : Auras d'unité > Liste d'ignorés globale"
