L["When enabled, WoW owns buff icons. MSUF hide categories and custom buff positioning do not filter Blizzard-rendered buffs, so Skyfury or Earth Shield can still appear."] = "Quand cette option est activée, WoW gère les icônes d'amélioration. Les catégories masquées de MSUF et le positionnement personnalisé des améliorations ne filtrent pas les améliorations affichées par Blizzard, donc Fureur-du-ciel ou Bouclier de terre peuvent encore apparaître."
L["When enabled, WoW owns debuff icons. MSUF hide categories and custom debuff positioning do not filter Blizzard-rendered debuffs."] = "Quand cette option est activée, WoW gère les icônes d'affaiblissement. Les catégories masquées de MSUF et le positionnement personnalisé des affaiblissements ne filtrent pas les affaiblissements affichés par Blizzard."
L["When enabled, WoW owns defensive icons. MSUF custom positioning and styling apply only when this is off or the renderer is MSUF Custom."] = "Quand cette option est activée, WoW gère les icônes défensives. Le positionnement et le style personnalisés de MSUF ne s'appliquent que si cette option est désactivée ou si le moteur de rendu est MSUF Custom."
