L["Double-click or use the settings button to open this element's settings."] = "Double-cliquez ou utilisez le bouton Paramètres pour ouvrir les paramètres de cet élément."
L["Right-click opens quick actions."] = "Un clic droit ouvre des actions rapides."
L["double-click/settings opens options - right-click actions - arrows nudge"] = "double-clic/réglages ouvre les options - clic droit : actions - flèches : décalage"
L["drag handles - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "poignées de déplacement - double-clic/réglages ouvre les options - actions par clic droit - Ctrl+molette zoom"
L["Click a handle to select - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "Cliquez sur une poignée pour sélectionner - double-clic/réglages ouvre les options - clic droit : actions - Ctrl+molette : zoom"
L["Preview tip: drag handles to move, double-click or use settings to open options, right-click for actions."] = "Astuce d'aperçu : faites glisser les poignées pour déplacer, double-cliquez ou utilisez les paramètres pour ouvrir les options, cliquez avec le bouton droit pour les actions."
