L["Hide center % sign"] = "Masquer le signe % au centre"
L["Group frames were enabled or disabled.\n\nA UI reload is required to fully apply this change.\n\nReload now?"] = "Les cadres de groupe ont été activés ou désactivés.\n\nUn rechargement de l'interface est nécessaire pour appliquer pleinement cette modification.\n\nRecharger maintenant ?"
L["|cffffd700MSUF:|r Group frames were enabled or disabled. Reload the UI with /reload."] = "|cffffd700MSUF:|r Les cadres de groupe ont été activées ou désactivées. Rechargez l'interface utilisateur avec /reload."
