L["Place your frames"] = "Placez vos cadres"
L["Target of target"] = "Cible de cible"
L["Focus target"] = "Cible de focalisation"
L["Boss frames"] = "Cadres de boss"
L["Party and raid layout"] = "Disposition des groupes et des raids"
L["Group health and text"] = "Vie et texte de groupe"
L["Group indicators"] = "Indicateurs Groupe"
L["Group auras"] = "Auras de groupe"
L["Bars and textures"] = "Barres et textures"
L["Cast bars"] = "Barres d'incantation"
L["Fonts and text"] = "Polices et texte"
L["Aura styling"] = "Style d'aura"
L["Menu and miscellaneous"] = "Menu et divers"
L["Class resources"] = "Ressources de classe"
L["Gameplay features"] = "Fonctionnalités de jeu"
L["Profiles and backup"] = "Profils et sauvegarde"
L["Review your guided setup"] = "Passez en revue votre configuration guidée"
L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "Ignorer cette étape personnelle utilise un guidage neutre et laisse la navigation, la recherche, la sauvegarde automatique, Annuler/Rétablir et la réinitialisation de la page inexpliquées."
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "Passer le placement des cadres laisse inexpliqués le déplacement des cadres entiers, l'alignement, le décalage fin et la sortie en toute sécurité."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "Ignorer le cadre du joueur laisse sa mise en page, son texte, ses indicateurs et ses options d'aura non révisés."
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "Ignorer le cadre cible laisse sa mise en page, son texte, ses indicateurs et ses options d'aura non révisés."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "Ignorer le cadre Focus laisse sa mise en page, son texte, ses indicateurs et ses options d'aura non révisés."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "Ignorer le cadre du familier laisse sa mise en page, son texte, ses indicateurs et ses options d'aura non révisés."
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "Ignorer la cible de la cible laisse ses options de mise en page, de texte et de visibilité non vérifiées."
L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "Ignorer la cible de focalisation laisse ses options de mise en page, de texte et de visibilité non révisées."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "Ignorer les cadres Boss laisse leurs options de mise en page, de texte, d'indicateurs et d'aura partagées sans examen."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Sauter la disposition des groupes laisse la taille du cadre, la croissance, le tri, la mise à l'échelle et l'ancrage non révisés."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "Sauter les barres de groupe laisse la présentation de la vie, de la ressource, du texte, de la portée et de la dissipation non révisée."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "Ignorer les auras de groupe laisse le comportement des buffs, des debuffs et des indicateurs de sorts de groupe sans examen."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Le saut des barres laisse les textures globales, les absorptions, les contours, les surbrillances et le comportement des ressources non révisés."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Passer les barres d'incantation laisse l'apparence des incantations, le texte, les sorts renforcés et les signaux d'interruption non révisés."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Ignorer les couleurs laisse les couleurs du cadre, de la ressource, de l'aura, de la classe, du texte et de la barre d'incantation non révisées."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Ignorer les polices laisse la police globale, le style du texte, les couleurs et le raccourcissement du nom sans révision."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Ignorer le style Aura laisse la taille, le temps de recharge, les cumuls, les barres de durée et l'ordre de buff/debuff non révisés."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "Ignorer Divers laisse la langue, le comportement des menus, le démarrage, les info-bulles et l'intégration du cadre Blizzard non révisés."
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "Sauter les ressources de classe laisse la disposition des classes, le comportement, le style, la visibilité et les affichages de ressource alternatifs non révisés."
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "Sauter le gameplay laisse les chronomètres de combat, le comportement de l'état, les basculements de classe et le réticule de combat non révisés."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "Ignorer les profils laisse la gestion des profils, l’attribution de spécialisation et la sauvegarde export/import non vérifiées."
L["Skipping the final review hides the summary, but does not change any setting."] = "Ignorer la révision finale masque le résumé, mais ne modifie aucun paramètre."
