L["Class resource preview and quick setup"] = "Aperçu des ressources de classe et configuration rapide"
L["Preview controls = inspect layouts and states · MSUF Edit Mode = whole-frame placement"] = "Contrôles d'aperçu = inspecter les mises en page et les états · Mode d'édition MSUF = placement du cadre entier"
L["Drag = inner position · gear/double-click = options · right-click = actions · Ctrl-wheel/drag = zoom/pan · Edit Mode = whole frame"] = "Glisser = position intérieure · engrenage/double-clic = options · clic droit = actions · Ctrl+molette/glisser = zoom/vue · Mode édition = cadre entier"
L["%s is highlighted. Adjust it live, keep it as is, or continue."] = "%s est mis en surbrillance. Ajustez-le en direct, conservez-le tel quel ou continuez."
L["Your focus: %s, with %s information."] = "Votre priorité : %s, avec un niveau d'information %s."
L["Choose one answer in each row. You can skip this personal step at any time."] = "Choisissez une réponse dans chaque ligne. Vous pouvez sauter cette étape personnelle à tout moment."
L["Drag whole frames, use arrows for precision, and Exit to keep your placement."] = "Faites glisser des cadres entiers, utilisez les flèches pour la précision, et Quitter pour conserver le placement."
L["Start with Preview, then follow each highlighted frame section."] = "Commencez par Aperçu, puis suivez chaque section de cadre en surbrillance."
L["Raid focus: compare Raid and Mythic scopes before reviewing each highlighted section."] = "Focus Raid : comparez les portées Raid et Mythique avant de revoir chaque section en surbrillance."
L["Solo focus: keep group defaults or prepare the Party scope for occasional groups."] = "Focus solo : conservez les paramètres de groupe par défaut ou préparez la portée Groupe pour des groupes occasionnels."
L["Dungeon focus: begin with Party or Mythic scope, then review each highlighted section."] = "Focus sur le donjon : commencez par la portée Groupe ou Mythique, puis passez en revue chaque section en surbrillance."
L["Compare the Party, Raid or Mythic scope that matters to you, then follow the highlights."] = "Comparez la portée Groupe, Raid ou Mythique qui vous intéresse, puis suivez les surbrillances."
L["Sample = visual only · tests = temporary · scope = shared/unit/group"] = "Échantillon = visuel uniquement · tests = temporaire · portée = partagée/unité/groupe"
L["Simulate casts here; position castbar handles in Preview or MSUF Edit Mode."] = "Simulez des incantations ici ; positionnez les poignées de la barre d'incantation en mode Aperçu ou Édition MSUF."
L["Use the scope selector for shared, unit and group text; compare readability in Preview."] = "Utilisez le sélecteur de portée pour le texte partagé, d'unité et de groupe ; comparer la lisibilité dans Aperçu."
L["Live/Dummy = display only · colored handles = saved positions · scope = shared/unit/group/custom"] = "Live/Dummy = affichage uniquement · poignées colorées = positions enregistrées · portée = partagée/unité/groupe/personnalisée"
L["Use the interactive preview for layouts and states; use Edit Mode for whole-frame placement."] = "Utilisez l'aperçu interactif pour les mises en page et les états ; utilisez le mode édition pour le placement du cadre entier."
L["Finish with a profile check and export a backup of your setup."] = "Terminez par une vérification de profil et exportez une sauvegarde de votre configuration."
L["Review your choices and skipped areas. Finish adds no extra setting changes."] = "Passez en revue vos choix et les zones ignorées. Terminer n’ajoute aucune modification de paramètre supplémentaire."
L["Clarity focus: prefer the simplest readable option in each highlighted section."] = "Focus sur la clarté : préférez l’option lisible la plus simple dans chaque section mise en surbrillance."
L["Combat-detail focus: inspect indicators, timers and visibility in each highlighted section."] = "Focus sur les détails du combat : inspectez les indicateurs, les minuteries et la visibilité dans chaque section en surbrillance."
L["Review the highlighted sections; previews update while your changes autosave."] = "Passez en revue les sections en surbrillance ; les aperçus sont mis à jour pendant que vos modifications sont enregistrées automatiquement."
