L["Unitframes, supported castbars, group containers, aura groups and the tooltip preview. Boss 1 moves the shared Boss layout."] = "Cadres d'unité, barres d'incantation prises en charge, conteneurs de groupe, groupes d'aura et aperçu de l'info-bulle. Boss 1 déplace la disposition Boss partagée."
L["Drag, select and align"] = "Faites glisser, sélectionnez et alignez"
