L["COPY FLOW - Open Copy To, select All categories, then apply the Player setup to another Unitframe."] = "COPIE - Ouvrez Copier vers, sélectionnez Toutes les catégories, puis appliquez la configuration du joueur à un autre cadre d'unité."
L["COPY FLOW - Open Copy To, select All categories, then press a destination to copy Party instantly."] = "COPIE - Ouvrez Copier vers, sélectionnez Toutes les catégories, puis appuyez sur une destination pour copier instantanément le groupe."
