L["Copies the complete Group Aura configuration, including Buff/Debuff filters, exact and category blacklists, layout, cooldown presentation, Strata, and dispel options."] = "Copie la configuration complète des auras de groupe, y compris les filtres Buff/Debuff, les listes noires exactes et de catégorie, la mise en page, la présentation du temps de recharge, les strates et les options de dissipation."
L["Copies every text slot with its content, size and position, plus this unit's font overrides: font, outline, shadow, text color and name shortening."] = "Copie chaque emplacement de texte avec son contenu, sa taille et sa position, ainsi que les remplacements de police de cette unité : police, contour, ombre, couleur du texte et abrègement des noms."
L["Copies the frame toggle, fill direction and health coloring, plus this unit's Bars overrides: bar textures, outline, highlight priority, gradient, absorb and heal prediction."] = "Copie l'activation du cadre, le sens de remplissage et la coloration de la vie, ainsi que les remplacements de barres de cette unité : textures, contour, priorité de surbrillance, dégradé, absorption et prévision de soins."
