L["Search Menu2 in everyday language to jump to the exact setting. Search only includes controls available in your active modules."] = "Recherchez dans Menu2 avec vos propres mots pour accéder directement au réglage voulu. La recherche ne couvre que les contrôles disponibles dans vos modules actifs."
L["Finish opens the Dashboard, where you can search settings across the active modules."] = "Terminer ouvre le tableau de bord, où vous pouvez rechercher des réglages dans tous les modules actifs."
L["Try searches such as 'Party frame width', 'Spell Icons', or 'Class Resources'. Search opens the matching setting in Menu2."] = "Essayez des recherches comme « largeur des cadres de groupe », « icônes de sorts » ou « ressources de classe ». La recherche ouvre le réglage correspondant dans Menu2."
