L["PART 2 - Build Party once, then copy it to Raid or Mythic Raid."] = "PARTIE 2 – Créez le groupe une fois, puis copiez-le dans Raid ou Raid mythique."
L["PART 3 - Shape Class Resources with its interactive preview and cooldown-aware anchoring."] = "PARTIE 3 - Façonnez les ressources de classe avec leur aperçu interactif et son ancrage prenant en compte le temps de recharge."
L["PARTY CORE - Change the new green setting and watch the Party Preview update."] = "CŒUR DU GROUPE - Modifiez le nouveau paramètre vert et regardez l'aperçu du groupe se mettre à jour."
L["PARTY IS THE MASTER - Adjust its frame basics, then copy the finished result to Raid or Mythic Raid."] = "LE GROUPE EST LE MODÈLE - Ajustez les bases de son cadre, puis copiez le résultat final dans Raid ou Raid mythique."
L["PLAYER CORE - Change the new green setting and watch the same Player Preview update."] = "CŒUR DU JOUEUR - Modifiez le nouveau paramètre vert et regardez l'aperçu du joueur se mettre à jour."
