L["Live preview is unavailable for this container. Sample mode remains available."] = "L'aperçu en direct n'est pas disponible pour ce conteneur. Le mode échantillon reste disponible."
L["Live preview updates after combat. Sample mode remains available."] = "Mises à jour d'aperçu en direct après le combat. Le mode échantillon reste disponible."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Épinglez manuellement les coéquipiers que vous souhaitez garder visibles pour la surveillance ou les sorts au clic. Les cadres prioritaires ne décident pas qui doit recevoir Prescience ou Puissance d'ébène. Configurez Cadres de groupe > Auras > Indicateurs de sort si vous souhaitez que les cadres de priorité hérités affichent Prescience, Puissance d'ébène, Sables changeants, Écailles torrides ou d'autres effets configurés."
L["Native · "] = "Natif ·"
L["No live "] = "Pas de direct"
L["No live member"] = "Aucun membre en direct"
L["No matching aura active"] = "Aucune aura correspondante active"
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Ouvrez Cadres de groupe > Priorité > Placement. Attachez la bande à droite, à gauche, en haut ou en bas du conteneur de groupe/raid actif, ou choisissez la position Libre et utilisez le déplaceur dédié aux cadres prioritaires en mode édition. La même page contrôle la croissance, l'espacement, l'écart d'ancrage et le décalage d'alignement."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Remplacement actif : cette portée conserve son propre style d'aura. Les modifications de style partagées ne le remplaceront pas tant que le remplacement n'aura pas été réinitialisé."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "Le style d’aura partagé constitue la référence pour les paramètres de texte, de balayage, de bordure et de minuterie d’aura des cadres d’unité. Groupe et Raid sont des portées de style des cadres de groupe avec leurs propres paramètres."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Les textures sont partagées, à l'exception des remplacements des cadres de groupe/raid. Les dégradés peuvent être personnalisés par unité ou par groupe."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Cette portée de groupe peut utiliser des textures et des dégradés personnalisés. Le Raid s'applique également au Raid Mythique."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Cette portée peut utiliser des dégradés et des paramètres de barre personnalisés. Les textures suivent toujours Partagé."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Cette portée suit les paramètres de barre partagés. Activez les paramètres personnalisés ici lorsque cette portée nécessite différents dégradés ou paramètres de barre."
L["Updates after combat"] = "Mises à jour après le combat"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "En groupe, définissez le raccourci de survol dans Cadres de groupe > Priorité. Survolez un cadre MSUF de groupe, raid ou prioritaire et appuyez sur le raccourci Cadres prioritaires pour épingler ou désépingler ce joueur. Les joueurs ne peuvent pas être ajoutés en tapant un nom ou en dehors du groupe actuel ; une épingle absente enregistrée attend et réapparaît lorsque ce joueur rejoint."
