-- 6.0 upgrade highlight: the rebuilt rounded corner style.
L["Rounded frames, corner for corner"] = "Des cadres arrondis, coin après coin"
L["Rounded unit and group frames now share one clean corner style with five strength levels, used by Health, embedded or detached Power, frame outlines and the aggro, dispel and highlight borders."] = "Les cadres d'unité et de groupe arrondis partagent désormais un style de coin net avec cinq niveaux d'intensité, utilisé par la Vie, la Ressource intégrée ou détachée, les contours de cadre et les bordures d'aggro, de dissipation et de survol."
L["Every rounded element follows the same geometry, so corners no longer disagree with each other or lose their mask after a reload."] = "Chaque élément arrondi suit la même géométrie : les coins ne se contredisent plus et ne perdent plus leur masque après un rechargement."
