L["Synchronized with Text Colors in the Fonts menu for this scope."] = "Synchronisé avec Couleurs du texte dans le menu Polices pour cette portée."
L["Open the shared font and colors used by every Aura scope."] = "Ouvre la police et les couleurs partagées utilisées par toutes les portées d'auras."
L["Tints unit-frame health bars when a configured debuff condition is active."] = "Teinte les barres de vie des cadres d'unité quand une condition de débuff configurée est active."
L["Shows a symbol naming the dispel type of an active debuff."] = "Affiche un symbole indiquant le type de dissipation d'un débuff actif."
L["Shows the raid subgroup number from the raid roster."] = "Affiche le numéro de sous-groupe issu de la liste du raid."
L["Shows the raid subgroup number. Party frames only display it while you are in an actual raid group."] = "Affiche le numéro de sous-groupe. Les cadres de groupe ne l'affichent que dans un vrai raid."
L["Independent of mouseover. Marks your current target in the selected group-frame types."] = "Indépendant du survol. Marque votre cible actuelle dans les types de cadres de groupe choisis."
L["Configure target highlighting in Appearance > Miscellaneous > Frame Highlights."] = "Configurez la mise en évidence de la cible dans Apparence > Divers > Surbrillances de cadre."
