L["Configure the Party portrait border color and opacity."] = "Configure la couleur et l'opacité de la bordure du portrait de groupe."
L["Scales frame size, fonts, and icons proportionally."] = "Met à l'échelle la taille du cadre, les polices et les icônes proportionnellement."
L["Buff/debuff positions stay relative to their anchors."] = "Les positions des buffs/débuffs restent relatives à leurs ancrages."
L["Automatically scale by group size."] = "Mettre à l'échelle automatiquement selon la taille du groupe."
L["Drag rows with mouse to reorder."] = "Faites glisser les lignes à la souris pour les réorganiser."
