L["Shared icon shape"] = "Forme d'icône partagée"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Les modes de visibilité ne s'appliquent qu'aux cadres d'unité et de groupe. Les info-bulles d'aura utilisent leurs propres options Afficher l'infobulle ; même Jamais ne les remplace. Les auras ne reprennent que l'apparence Blizzard/MSUF choisie et le placement du curseur."
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "S'applique à toute la barre d'incantation : barre, icône, tous les textes, effets et bordure. Tous les éléments MSUF partagent cet ordre 0-30 ; chaque partie de la couche 30 est dessinée au-dessus de chaque partie de la couche 29."
