L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Ajoute les boutons d'enchantement d'arme temporaire de Blizzard au conteneur de buffs du joueur. Il s'agit d'un réglage partagé unique qui utilise le flux d'auras natif, sans minuteur ni OnUpdate MSUF."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "Ajoute un ID exact d'aura néfaste absent de la liste sélectionnée. L'aura reste limitée à votre cible actuelle et à vos propres auras."
L["Adds one exact buff to this frame's blacklist."] = "Ajoute un buff exact à la liste noire de ce cadre."
L["Adds one exact buff to this group's blacklist."] = "Ajoute un buff exact à la liste noire de ce groupe."
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "Ajoute une aura néfaste exacte à la liste noire Cible, Focus ou Boss. Blizzard n'applique des filtres SpellID arbitraires que tant que l'unité ne peut pas être assistée."
L["All Buffs"] = "Tous les buffs"
L["All Debuffs"] = "Tous les débuffs"
L["All roles"] = "Tous les rôles"
L["Always excludes auras without a duration, even when Blizzard token filters are disabled."] = "Exclut toujours les auras sans durée, même lorsque les filtres de jeton Blizzard sont désactivés."
L["Always excludes auras without a duration."] = "Exclut toujours les auras sans durée."
L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "Exclut toujours les auras sans durée. Reste actif lorsque les filtres de jeton sont désactivés."
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "Exclut toujours les auras sans durée. Cette règle native prévaut sur les listes noires et blanches de SpellID."
L["Anchor To Class Resource"] = "Ancrer à la ressource de classe"
L["Any Dispel Type"] = "Tout type de dissipation"
L["Any dispel type"] = "Tout type de dissipation"
L["Applicable by Me (Raid)"] = "Applicable par moi (raid)"
L["Applies to every UnitFrame and GroupFrame icon of this Aura type. Spell Icons use the Buff appearance."] = "S'applique à toutes les icônes des cadres d'unité et de groupe de ce type d'aura. Les Icônes de sorts utilisent l'apparence des buffs."
L["Aura sort order"] = "Ordre de tri des auras"
L["Aura sorting"] = "Tri des auras"
L["Aura tooltip"] = "Info-bulle d'aura"
L["Auto breakpoints"] = "Points de rupture automatiques"
L["Auto fit"] = "Ajustement automatique"
L["Auto fit pips"] = "Ajuster les segments automatiquement"
L["Auto-blacklist from Debuffs"] = "Liste noire automatique depuis les débuffs"
L["Auto-blacklist from player buffs"] = "Liste noire automatique depuis les buffs du joueur"
L["Auto: Essential Cooldowns"] = "Auto : temps de recharge essentiels"
L["Auto: Unit Frame"] = "Auto : cadre d'unité"
L["Auto: Utility Cooldowns"] = "Auto : temps de recharge utilitaires"
L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "Barre seule masque l'icône de l'aura. Icône + barre conserve l'icône et y trace la barre de durée."
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "Barre conserve la barre d'état normale. Suivre la ressource du joueur reprend la forme de la ressource du joueur détachée. Orbe utilise un unique remplissage vertical."
L["Big Defensive"] = "Grande défensive"
L["Big Defensive Player"] = "Grande défensive (joueur)"
L["Blizzard castbar"] = "Barre d'incantation Blizzard"
L["Blizzard ring + symbol"] = "Anneau + symbole Blizzard"
L["Blizzard symbol"] = "Symbole Blizzard"
L["Blocks every aura in the selected curated MSUF set."] = "Bloque toutes les auras du jeu sélectionné de MSUF."
L["Blocks only the selected aura from the curated set."] = "Bloque uniquement l'aura sélectionnée du jeu proposé."
L["Cancelable Player"] = "Annulable (joueur)"
L["Castbar Border"] = "Bordure de la barre d'incantation"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "Modifie uniquement la barre de ressource du joueur détachée. La forme de ressource de classe à gauche ne modifie que les ressources de classe."
L["Class Resource Preview"] = "Aperçu de la ressource de classe"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "La ressource de classe et la ressource du joueur suivent les cadres existants. Personnalisé utilise le curseur ci-dessous. La largeur n'est résolue qu'au rafraîchissement de la disposition."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "Contrôle uniquement le contour de la seconde barre de vie. Barre utilise les quatre bordures extérieures ; les formes utilisent leur texture de bord fixe. 0 désactive uniquement le contour."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "Contrôle uniquement cette seconde barre de vie. Le texte de vie normal du cadre du joueur reste distinct."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Contrôle cette rangée d'auras indépendamment. Toujours / Hors combat / Modificateur / Jamais, sous Style global > Divers, n'affectent que les cadres d'unité et de groupe. Les auras ne reprennent que l'aspect Blizzard/MSUF choisi et le placement du curseur."
L["Cooldown swipe direction"] = "Sens du balayage de temps de recharge"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "Fonction principale activée par défaut pour les nouveaux profils et une seule fois pour les profils existants. Elle fonctionne comme une barre de buffs défensifs normale même sans portrait activé. Désactivez-la pour supprimer à la fois la barre et l'affichage à la position du portrait."
L["Crowd Control"] = "Contrôle de foule"
L["Curated DoT auras for this game version. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Auras de DoT sélectionnées pour cette version du jeu. Le suivi est limité à l'unité de ce UnitFrame et à vos propres auras ; les réglages Boss se lient séparément à boss1 jusqu'à boss5."
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Auras de DoT sélectionnées pour Retail 12.0+ et 12.1. Le suivi est limité à l'unité de ce cadre d'unité et à vos propres auras ; les réglages Boss se lient séparément à boss1 jusqu'à boss5."
L["Custom Spell ID"] = "ID de sort personnalisé"
L["Dark Border"] = "Bordure sombre"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "Désactivé par défaut. L'implémentation native de Blizzard active un OnUpdate par image sur chaque bouton d'aura visible dès que cette aura possède une fenêtre de pandémie calculée ; cela peut commencer avant que l'alerte ne devienne visible."
L["Dispellable by Group"] = "Dissipable par le groupe"
L["Dispellable by Me (Raid)"] = "Dissipable par moi (raid)"
L["Dispellable by group"] = "Dissipable par le groupe"
L["Down (Single Column)"] = "Vers le bas (colonne unique)"
L["Duration bar display"] = "Affichage de la barre de durée"
L["Duration bar fill mode"] = "Mode de remplissage de la barre de durée"
L["Duration bar position"] = "Position de la barre de durée"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "Intensité du bord de chaque forme de ressource du joueur détachée, y compris Barre, Rond, Cristal et Orbe. 0 désactive uniquement ce bord."
L["Elapsed / Total"] = "Écoulé / total"
L["Enable defensive buffs"] = "Activer les buffs défensifs"
L["Enable tracked DoTs"] = "Activer les DoTs suivis"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "Saisissez un ID de sort, collez un lien de sort ou tapez un nom de sort. L'aura bénéfique visible est reconnue même si son ID de buff diffère de l'ID du sort lancé."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "Saisissez un ID de sort, collez un lien de sort ou tapez un nom de sort. Cette liste blanche suit des ID de sort exacts."
L["Essential cooldown viewer"] = "Visionneuse des temps de recharge essentiels"
L["Exact aura tracking"] = "Suivi exact des auras"
L["External Defensive"] = "Défensive externe"
L["External Defensive Player"] = "Défensive externe (joueur)"
L["Fill Mode"] = "Mode de remplissage"
L["Focus off"] = "Focus désactivé"
L["Focus on"] = "Focus activé"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global suit le mode de couleur de vie normal de MSUF. Couleur de classe impose la couleur de votre classe. Mode sombre impose la couleur de barre sombre configurée. Dégradé de points de vie ne colore que cette seconde barre de vie selon la vie actuelle."
L["Global icon shape"] = "Forme d'icône globale"
L["HP Color"] = "Couleur de la vie"
L["HP Outline"] = "Contour de la vie"
L["HP Shape"] = "Forme de la barre de vie"
L["HP only"] = "Vie uniquement"
L["Healers only"] = "Soigneurs uniquement"
L["Hide permanent auras"] = "Masquer les auras permanentes"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "Masque les ID de sort de DoT sélectionnés pour cette portée du conteneur de débuffs normal du même cadre d'unité tant que DoTs sur la cible est activé. La liste noire de Blizzard fonctionne par SpellID : le même sort lancé par un autre joueur y est donc également masqué."
L["Highest priority only"] = "Priorité la plus élevée uniquement"
L["Icon Border & Shadow"] = "Bordure et ombre de l'icône"
L["Include Nameplate-only"] = "Inclure les barres d'unité uniquement"
L["Inside Left"] = "Intérieur gauche"
L["Inside Right"] = "Intérieur droit"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "Maintient la ressource du joueur détachée rattachée à la barre de ressource de classe. Les réglages de la ressource du joueur sont désactivés tant que cette liaison est active."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "Conserve la taille et la position configurées du portrait comme ancre invisible afin que l'icône défensive puisse y rester alors que le portrait lui-même est désactivé."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "Conserve la taille, la position et la forme configurées du portrait comme ancre invisible pour les DoTs suivis alors que le portrait lui-même est désactivé."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "Limite les icônes de DoT simultanées au portrait de 1 à 8. Les icônes supplémentaires s'étendent vers l'extérieur selon le sens de croissance configuré pour cette rangée de DoT."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "Limite le nombre d'icônes défensives simultanées au portrait de 1 à 8. Les profils existants restent à 1 tant que cette valeur n'est pas modifiée."
L["Lists every MSUF slash command in chat, diagnostics included."] = "Liste dans le canal de discussion toutes les commandes slash de MSUF, diagnostics inclus."
L["Max portrait icons"] = "Icônes max. au portrait"
L["Maximum debuff duration"] = "Durée maximale des débuffs"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "Déplace ensemble tous les emplacements de texte de la ressource du joueur détachée. Les réglages X/Y d'emplacement ci-dessous ajoutent des décalages individuels."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "Sort la barre de ressource du joueur du cadre d'unité. Ancrer la relie à la pile des ressources de classe ; Synchroniser n'en reprend que la largeur."
L["Native Aura Flow"] = "Flux d'auras natif"
L["Blizzard Buff & Debuff Frames"] = "Cadres des améliorations et affaiblissements Blizzard"
L["Hide Blizzard Buff and Debuff Frames"] = "Masquer les cadres d'améliorations et d'affaiblissements Blizzard"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Masque uniquement le cadre des améliorations du joueur de Blizzard et les icônes d'affaiblissements normales près de la minicarte. Les auras privées et les avertissements d'affaiblissements mortels restent visibles."
L["Buffs hidden"] = "Améliorations masquées"
L["Buffs visible"] = "Améliorations visibles"
L["Debuffs hidden"] = "Affaiblissements masqués"
L["Debuffs visible"] = "Affaiblissements visibles"
L["Hide Blizzard Buff Frame"] = "Masquer le cadre des améliorations Blizzard"
L["Hide Blizzard Debuff Frame"] = "Masquer le cadre des affaiblissements Blizzard"
L["Hides Blizzard's player Buff Frame near the minimap."] = "Masque le cadre des améliorations du joueur de Blizzard près de la minicarte."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Masque uniquement les icônes d'affaiblissements normales de Blizzard près de la minicarte. Les auras privées et les avertissements d'affaiblissements mortels restent visibles."
L["Native size"] = "Taille native"
L["Native stealable marker"] = "Marqueur natif de vol de magie"
L["Native weapon enchant auras"] = "Auras natives d'enchantement d'arme"
L["No roles"] = "Aucun rôle"
L["No width limit"] = "Aucune limite de largeur"
L["Not Cancelable"] = "Non annulable"
L["Not Cancelable Player"] = "Non annulable (joueur)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "Désactivé affiche les débuffs de toute durée. Sinon, les débuffs dont la durée totale dépasse ce nombre de secondes sont masqués."
L["One per dispel type"] = "Un par type de dissipation"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "Ouvre le thème global d'icônes d'aura : bordure, ombre, couleurs, marge de rangée et enchantements d'arme natifs du joueur. Le Style de conteneur de ce cadre reste ici."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "Interpolation facultative pour cette seconde barre de vie. Désactivée, les mises à jour natives directes SetValue sont conservées."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "Mode de présentation facultatif ; la fonction Buffs défensifs ne nécessite pas de portrait. Avec un portrait activé, la première icône l'occupe. Portrait désactivé, activez l'option de position ci-dessous pour y maintenir les icônes ; sinon MSUF revient sans risque à la barre défensive normale."
L["Orb Size"] = "Taille de l'orbe"
L["Pandemic Warning & Style"] = "Alerte de pandémie et style"
L["Pandemic color"] = "Couleur de pandémie"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "Place le texte de la ressource du joueur sur la barre de ressource détachée. Désactivé, ce même texte reste positionné par la disposition de texte normale."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "Place la barre de durée sur le bord supérieur ou inférieur de l'emplacement d'aura."
L["Player Text Outline"] = "Contour du texte du joueur"
L["Power Bar Outline"] = "Contour de la barre de ressource"
L["Power Text On Bar"] = "Texte de ressource sur la barre"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "Les ancres de ressource utilisent la barre de ressource du joueur lorsqu'elle est visible ; sinon la barre de vie revient à l'ancre de ressource de classe."
L["Raid In Combat"] = "Raid en combat"
L["Raid In Combat Player"] = "Raid en combat (joueur)"
L["Raid Player"] = "Raid (joueur)"
L["Remaining / Total"] = "Restant / total"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "Restant diminue à mesure que l'aura expire. Écoulé augmente jusqu'à l'expiration de l'aura."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "En dessous de cette valeur, le temps restant utilise une décimale. Les minuteurs affichent des secondes sans unité en dessous d'une minute et des minutes localisées au-dessus. Utilisez 0 pour n'afficher que des secondes entières."
L["Remove from blacklist"] = "Retirer de la liste noire"
L["Remove from whitelist"] = "Retirer de la liste blanche"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "Affiche une seconde barre de vie native du joueur. La barre de vie normale du cadre du joueur n'est pas modifiée : vous pouvez donc afficher la vie deux fois."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "Remplace la rangée de DoT normale par des icônes à la taille du portrait. La première icône suit exactement la largeur, la hauteur et la forme du portrait de ce cadre."
L["Runs /msuf reset for frame positions and visibility."] = "Exécute /msuf reset pour les positions et la visibilité des cadres."
L["Second Player HP Bar"] = "Seconde barre de vie du joueur"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "Définit la portée de police du joueur utilisée par le texte de ressource détaché. Le nom du joueur et le texte de vie partagent ce réglage de contour."
L["Show DoTs at portrait position"] = "Afficher les DoTs à la position du portrait"
L["Show buffs at portrait position"] = "Afficher les buffs à la position du portrait"
L["Show cooldown text on portrait"] = "Afficher le texte de temps de recharge sur le portrait"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "Affiche la durée restante du buff défensif actif au-dessus de son icône de portrait. Blizzard met le texte à jour nativement."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "Affiche ci-dessous la ressource de la classe ou spécialisation sélectionnée sans modifier votre personnage, votre spécialisation ni vos réglages enregistrés."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "Affiche la durée restante du DoT suivi au-dessus de son icône de portrait. Blizzard met la durée à jour nativement."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "Préréglages simples pour le texte de la ressource du joueur lorsque la ressource détachée est gérée par les ressources de classe. Emplacements personnalisés conserve la disposition d'emplacements actuelle jusqu'à ce que vous choisissiez un préréglage."
L["Smooth Fill"] = "Remplissage fluide"
L["Spell Text"] = "Texte du sort"
L["Stops blocking this aura."] = "Cesse de bloquer cette aura."
L["Sync Width"] = "Synchroniser la largeur"
L["Tanks only"] = "Tanks uniquement"
L["Target DoT"] = "DoT sur la cible"
L["Target off"] = "Cible désactivée"
L["Target on"] = "Cible activée"
L["Time Text"] = "Texte de temps"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "Suivre ce buff défensif prédéfini. Le réglage s'applique à la fois à la barre défensive et à l'icône de portrait facultative."
L["Tracked buffs viewer"] = "Visionneuse des buffs suivis"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "Suit les auras néfastes que vous sélectionnez sur l'unité de ce cadre d'unité. Les cadres de boss utilisent leurs propres jetons d'unité, de boss1 à boss5."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "Active ou désactive les filtres de jeton Blizzard pour ce cadre. La première modification crée automatiquement des règles propres au cadre ; les règles partagées migrées restent partagées jusqu'à modification."
L["Unavailable cast fill"] = "Remplissage d'incantation indisponible"
L["Up (Single Column)"] = "Vers le haut (colonne unique)"
L["Use Player HP Text"] = "Utiliser le texte de vie du joueur"
L["Use portrait position while portrait is off"] = "Utiliser la position du portrait quand le portrait est désactivé"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "Utilisé uniquement lorsque cette barre de vie est explicitement réglée sur Orbe. Suivre la ressource du joueur hérite à la place de la taille d'orbe de la ressource du joueur."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Utilise le filtre de vol de magie AuraButton de Blizzard 12.1. Il n'ajoute aucun scan d'auras, minuteur ni OnUpdate MSUF."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "Utilise les réglages du texte de vie du joueur et copie le texte déjà affiché lorsqu'il est à jour. Les valeurs locales de texte X/Y appartiennent toujours à cette barre."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "Utilise la largeur de la ressource de classe pour la ressource du joueur détachée sans que les ressources de classe s'approprient ses réglages."
L["Utility cooldown viewer"] = "Visionneuse des temps de recharge utilitaires"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "Visible derrière la portion de vie remplie. À 100 % de vie, le remplissage couvre l'arrière-plan ; un contour de 0 ne désactive pas cette texture."
L["Weapon Enchants Off"] = "Enchantements d'arme désactivés"
L["Weapon Enchants On"] = "Enchantements d'arme activés"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "Tant que la barre défensive ou l'icône de portrait est activée, masque de la rangée de buffs normale du joueur chaque défensive suivie activée. Les entrées défensives désactivées y restent visibles."
L["Whole frame"] = "Cadre entier"
L["Width Mode"] = "Mode de largeur"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "Teinte d'arrière-plan de la barre Couleur personnalisée en mode sombre arrière-plan fond bg opacité alpha background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "Bases du cadre Activer Conditions de chargement Opacité Fondu de distance joueur cible focus familier absent invisible"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "Bases du cadre Remplissage lisse Barre de ressource Remplissage lisse animation de vie animation de ressource smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "Général Utiliser les cadres de groupe MSUF Si ce commutateur est désactivé activer désactiver masquer raid groupe mythique"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "Cadres groupe/raid Disposition Remplissage lisse de la vie Texte de vie Barre de ressource Remplissage lisse groupe raid smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "Cadres groupe/raid Disposition Opacité transparence fondu cible en combat hors combat alpha cadre entier barres vie arrière-plan remplissage de vie piste de vie conserver la couleur de vie"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "Le Mode édition MSUF déplace les cadres et les barres d'incantation prises en charge. Le placement des icônes d'aura se règle depuis la page de chaque unité > Auras ou dans Cadres groupe/raid > Auras."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "Divers style global langue comportement du menu avis de démarrage info-bulles cadres Blizzard minicarte sons"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "Raccourcissement du nom Utiliser des réglages personnalisés pour cette portée Remplace groupe raid raccourcissement des noms des cadres de groupe remplacement de police modifications partagées"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "Ouvrez Apparence > Auras pour le texte de temps de recharge, le texte de cumuls, le balayage et le style de barre de durée liés à la portée. Les couleurs des minuteurs restent sous Couleurs > Auras."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "Ouvrez Cadres de boss > Auras > Débuffs. Les entrées de liste noire par SpellID, les filtres Blizzard, le placement et l'aperçu s'y trouvent réunis ; le style reste sous Apparence > Auras."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "Ouvrez Style global > Divers > Info-bulles des cadres d'unité pour contrôler la source, l'ancrage, le mode de visibilité et la touche de modification des info-bulles des cadres d'unité et de groupe MSUF."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "Ouvrez Style global > Divers pour la langue, le comportement du menu, les avis de démarrage, les info-bulles, les cadres Blizzard, l'icône de minicarte et les sons."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "Ouvrez Cadres groupe/raid > Disposition > Fondu de distance. Affecte choisit le fondu du cadre ou de la vie, et les curseurs alpha contrôlent l'opacité hors de portée et hors ligne."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "Ouvrez Cadres groupe/raid > Disposition > Opacité. Opacité contrôle l'alpha en combat et hors combat ; Cible du fondu choisit le cadre entier, les barres, la vie ou l'arrière-plan. Les calques Arrière-plan et Vie définissent la couleur de base ainsi que l'opacité du remplissage et de la piste de vie."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "Ouvrez Cadres groupe/raid > Disposition pour le Remplissage lisse de la vie. Pour les barres de ressource des cadres de groupe, ouvrez Cadres groupe/raid > Disposition > Barre de ressources > Remplissage lisse."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "Ouvrez Cadres groupe/raid > Disposition, choisissez Groupe, Raid ou Mythique en haut, puis désactivez Utiliser les cadres de groupe MSUF. Utilisez Si ce commutateur est désactivé pour choisir si les cadres Blizzard s'affichent normalement ou si les deux systèmes de cadres restent masqués."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "Ouvrez Cadres groupe/raid > Disposition. Bases du cadre et Tri contrôlent la visibilité du joueur et de vous-même ainsi que l'ordre des unités dans les cadres de groupe."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Ouvrez Cadres groupe/raid > Disposition. Bases du cadre/Disposition contrôle la largeur, la hauteur, l'espacement, les colonnes et la croissance ; Mise à l'échelle du cadre contrôle le comportement d'échelle."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Ouvrez Cadres groupe/raid > Statut et indicateurs pour les icônes d'état, le rôle/chef/assistant, la vérification de préparation, la lueur de focus et les autres indicateurs d'état des cadres de groupe."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "Ouvrez Joueur > Auras, puis désactivez Buffs pour le cadre du joueur. Le style de texte et de temps de recharge lié à la portée reste sous Apparence > Auras."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "Ouvrez une page d'unité, puis utilisez Fondu de distance. Il est disponible pour Cible, Cible de la cible, Focus, Cible du focus, Familier et Boss."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "Ouvrez le cadre d'unité concerné > Auras pour la taille des icônes, le placement et les filtres. Utilisez Apparence > Auras pour le texte et le style de temps de recharge liés à la portée."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "Ouvrez le cadre d'unité concerné > Auras ou Cadres groupe/raid > Auras et réduisez le nombre d'auras visibles, le texte des minuteurs ou les règles de filtre natives inutiles."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "Ouvrez le cadre d'unité concerné > Auras, choisissez Buffs ou Débuffs, puis ajustez les filtres, la taille des icônes, les rangées, les limites et l'espacement. Les réglages groupe/raid se trouvent dans Cadres groupe/raid > Auras."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Ouvrez la page d'unité > Auras ou la fenêtre de position des auras pour le placement des auras du cadre d'unité. Les icônes de buff et de débuff se configurent comme une disposition d'auras et ne se déplacent pas via le Mode édition MSUF."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "Fondu de distance cadre de groupe vérification de portée raid groupe hors de portée alpha opacité hors ligne affecte cadre vie"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "Fondu de distance cadre d'unité vérification de portée vérification de distance hors de portée alpha de portée cible cible de la cible focus cible du focus familier boss"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "Texture arrondie Texture de cadre arrondie Cadres d'unité Cadres de groupe Barres de ressource Surbrillances au survol cadres arrondis coins arrondis"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "Icônes d'état Indicateur Niveau Activé Point d'attache Décalage X Décalage Y Taille Calque texte de niveau indicateur de niveau niveau du joueur niveau de la cible"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "Texte point d'attache décalage taille de police calque ordre de dessin espacement espacement divisé chevauchements barres portraits icônes d'état"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "Utilisez Cadres groupe/raid > Disposition pour la taille et l'espacement des cadres, Auras pour le placement des buffs/débuffs et Statut et indicateurs pour les icônes d'état à position fixe."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "Utilisez les pages Cadres groupe/raid : Disposition pour la taille, la croissance, le tri, les barres et le texte ; Auras pour le placement des buffs/débuffs et Statut et indicateurs pour les icônes d'état."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "Utilisez la page d'unité pour les commutateurs de barre d'incantation par unité et Style global > Barre d'incantation pour les textures, le sens, le texte et les options d'interruption partagés."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "Bienvenue dans les Ressources de classe !\n\nSouhaitez-vous configurer automatiquement une\nbarre de classe détachée placée au-dessus de vos\ntemps de recharge essentiels ?\n\nCela règle en un clic la visibilité de la ressource\nde classe, l'ancrage, l'alignement de largeur et la\nressource du joueur détachée.\n\nVous pourrez toujours le refaire plus tard via le\nbouton |cff00ff00Configuration rapide : barre de classe|r ci-dessous."

