-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "Confirmer l'ancrage"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Ne confirmez que si vous voulez que toute la disposition du cadre d'unité se déplace avec vos temps de recharge."
L["Keep independent"] = "Garder indépendant"
L["MSUF detected %s."] = "MSUF a détecté %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF va maintenant ancrer la disposition globale du cadre d'unité à Essential Cooldown Manager."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Rien ne bougera tant que vous n'aurez pas confirmé à l'étape suivante. Si vous choisissez Garder indépendant, vous pourrez activer l'ancrage CDM à tout moment dans le Mode édition MSUF ou sous Unité > Ancrage dans le menu MSUF."
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Rien ne bougera tant que vous n'aurez pas confirmé à l'étape suivante. Vous pourrez changer cela plus tard dans le Mode édition MSUF."
L["Second confirmation for %s."] = "Seconde confirmation pour %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Voulez-vous que MSUF ancre la disposition globale du cadre d'unité à Essential Cooldown Manager ?"
L["MISSION %d/%d - %d XP"] = "MISSION %d/%d - %d EXP"
L["Perf..."] = "Perf..."
L["Portrait Y"] = "Portrait Y"
L["Section %d / %d · Action %d / %d · %s"] = "Section %d / %d · Action %d / %d · %s"
L["Section %d / %d · Option %d / %d · %s"] = "Section %d / %d · Option %d / %d · %s"
-- Menu localization pass 2026-08-06 (part 7): native Player resource pings.
L["Enable native Player resource pings (12.1)"] = "Activer les pings natifs de ressource du joueur (12.1)"
L["Native Player resource pings"] = "Pings natifs de ressource du joueur"
L["Contextual pings over the MSUF Player frame can call out health and, when Blizzard supports it, mana. Blizzard does not expose separate Health/Power selection or Energy, Rage and Focus pings. The portrait keeps the normal Player unit ping and radial wheel."] = "Les pings contextuels sur le cadre Joueur de MSUF peuvent signaler la santé et, lorsque Blizzard le permet, le mana. Blizzard n’expose ni sélection distincte Santé/Ressource, ni pings d’énergie, de rage ou de focalisation. Sur le portrait, le ping d’unité Joueur normal et la roue radiale restent disponibles."
L["Edits the selected element's X position. Positive values move right. Arrow keys and dragging update the same position."] = "Modifie la position X de l'élément sélectionné. Les valeurs positives le déplacent vers la droite. Les flèches et le glissement actualisent la même position."
L["Edits the selected element's Y position. Positive values move up. Arrow keys and dragging update the same position."] = "Modifie la position Y de l'élément sélectionné. Les valeurs positives le déplacent vers le haut. Les flèches et le glissement actualisent la même position."
L["Exact X position"] = "Position X exacte"
L["Exact Y position"] = "Position Y exacte"
L["External frame"] = "Cadre externe"
L["Next page"] = "Page suivante"
L["Previous page"] = "Page précédente"

L["UnitFrame Debuff blacklist"] = "Liste noire des affaiblissements des cadres d'unité"
L["You can blacklist any debuff applied by the player on the %s UnitFrame using its exact Spell ID. The debuff on the unit can carry a different Spell ID than the spell you cast - use the ID from the debuff itself."] = "Vous pouvez placer sur liste noire tout affaiblissement appliqué par le joueur sur le cadre d’unité %s via son ID de sort exact. L’affaiblissement sur l’unité peut porter un ID de sort différent de celui du sort lancé - utilisez l’ID de l’affaiblissement lui-même."
L["Spell ID vs. aura ID"] = "ID de sort vs ID d’aura"
L["The aura on the unit can use a different Spell ID than the spell you cast. Enter the ID shown on the aura itself. After adding, MSUF checks the live unit and warns when only a same-named aura with a different ID is active."] = "L’aura sur l’unité peut utiliser un ID de sort différent de celui du sort lancé. Saisissez l’ID affiché par l’aura elle-même. Après l’ajout, MSUF vérifie l’unité et avertit si seule une aura du même nom avec un autre ID est active."
L["%s (#%d) is active on this frame right now - blacklist entry verified."] = "%s (#%d) est actuellement actif sur ce cadre - entrée de la liste noire vérifiée."
L["#%d is not active on this frame, but %s is currently active as #%d. The aura's ID can differ from your cast's Spell ID."] = "#%d n’est pas actif sur ce cadre, mais %s est actuellement actif sous #%d. L’ID de l’aura peut différer de l’ID du sort lancé."
L["Block #%d instead"] = "Bloquer #%d à la place"
L["Active auras on this frame"] = "Auras actives sur ce cadre"
L["Shows the result of the last scan: every readable aura with the exact ID it carried, plus everything captured earlier this session. Press Rescan to scan the current unit - blocking from this list always uses the aura's own ID. Secret auras cannot be listed."] = "Affiche le résultat de la dernière analyse : chaque aura lisible avec son ID exact, plus tout ce qui a été capturé durant cette session. Cliquez sur Réanalyser pour analyser l’unité actuelle - bloquer depuis cette liste utilise toujours l’ID de l’aura elle-même. Les auras secrètes ne peuvent pas être listées."
L["No scan yet - click Rescan"] = "Aucune analyse pour le moment - cliquez sur Réanalyser"
L["Start combat scan"] = "Démarrer l’analyse en combat"
L["Closes the menu and keeps scanning this frame's auras until combat ends or you press Stop. Every aura an addon can block is captured with its icon - auras Blizzard keeps secret cannot be blocked by any addon."] = "Ferme le menu et continue d’analyser les auras de ce cadre jusqu’à la fin du combat ou jusqu’à ce que vous appuyiez sur Arrêter. Chaque aura qu’un addon peut bloquer est capturée avec son icône - les auras gardées secrètes par Blizzard ne peuvent être bloquées par aucun addon."
L["Scanning auras - creating a list"] = "Analyse des auras - création d’une liste"
L["%d captured so far"] = "%d capturées pour l’instant"
L["%d captured so far - %d hidden by Blizzard"] = "%d capturées pour l’instant - %d masquées par Blizzard"
L["Hidden auras are Blizzard-secret - no addon can block them. Everything blockable was captured."] = "Les auras masquées sont des secrets Blizzard - aucun addon ne peut les bloquer. Tout ce qui peut être bloqué a été capturé."
L["Blocked by Blizzard during this fight - resumes automatically. In instances, use the curated presets."] = "Bloqué par Blizzard pendant ce combat - reprend automatiquement. En instance, utilisez les ensembles prédéfinis."
L["Blizzard is blocking aura scanning right now (encounter, Mythic+, or PvP match). Use the curated presets - they cover everything blockable in instanced content."] = "Blizzard bloque l’analyse des auras en ce moment (rencontre, Mythique+ ou match JcJ). Utilisez les ensembles prédéfinis - ils couvrent tout ce qui peut être bloqué en instance."
L["Scan complete: %d auras readable right now, %d captured this session. %d more are hidden by Blizzard and cannot be blocked by any addon."] = "Analyse terminée : %d auras lisibles actuellement, %d capturées dans cette session. %d autres sont masquées par Blizzard - aucun addon ne peut les bloquer."
L["Stop scan"] = "Arrêter"
L["Block selected aura"] = "Bloquer l’aura sélectionnée"
L["Blocks the selected aura using the exact ID it carries right now."] = "Bloque l’aura sélectionnée en utilisant l’ID exact qu’elle porte actuellement."
L["No readable auras right now"] = "Aucune aura lisible pour le moment"
L["Rescan"] = "Réanalyser"
L["Re-reads the auras on the current unit and adds everything it sees to this session's captured list - works in combat too. Shift-click clears the captured list."] = "Relit les auras de l’unité actuelle et ajoute tout ce qui est vu à la liste capturée de cette session - fonctionne aussi en combat. Maj + clic vide la liste capturée."
L["%s - captured"] = "%s - capturée"
L["Scan complete: %d auras readable right now, %d captured this session."] = "Analyse terminée : %d auras lisibles actuellement, %d capturées dans cette session."

-- Finalisation de la localisation complète issue de Menu2.
L["Aura settings are only available for Player, Target, Focus, and Boss Frames."] = "Les réglages des auras ne sont disponibles que pour les cadres Joueur, Cible, Focalisation et Boss."
L["Aura settings were skipped for unsupported UnitFrames."] = "Les réglages des auras ont été ignorés pour les cadres d’unité non pris en charge."
L["Blizzard animated Zzz"] = "Zzz animés de Blizzard"
L["Bottom half"] = "Moitié inférieure"
L["Castbar settings are only available for Player, Target, Focus, and Boss Frames."] = "Les réglages de la barre d’incantation ne sont disponibles que pour les cadres Joueur, Cible, Focalisation et Boss."
L["Castbar settings were skipped for UnitFrames without Castbars."] = "Les réglages de la barre d’incantation ont été ignorés pour les cadres d’unité sans barre d’incantation."
L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "La modification de cette valeur sélectionne Largeur manuelle. Pour le Joueur, elle désactive aussi Synchroniser la largeur avec la ressource de classe afin que la nouvelle largeur soit appliquée immédiatement."
L["Current target only"] = "Cible actuelle uniquement"
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Modifie le décalage X local de l’élément enfant sélectionné. Les valeurs positives le déplacent vers la droite. Les touches fléchées et le glissement mettent à jour le même décalage."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Modifie le décalage Y local de l’élément enfant sélectionné. Les valeurs positives le déplacent vers le haut. Les touches fléchées et le glissement mettent à jour le même décalage."
L["Exact X offset"] = "Décalage X exact"
L["Exact Y offset"] = "Décalage Y exact"
L["Full texture"] = "Texture complète"
L["Height (0 = auto)"] = "Hauteur (0 = auto)"
L["Highlight texture"] = "Texture de surbrillance"
L["No copy categories selected."] = "Aucune catégorie de copie sélectionnée."
L["Nothing was copied."] = "Rien n’a été copié."
L["Outline style"] = "Style du contour"
L["Rounded frames ignore True Outline and Texture styles and keep the solid outline color."] = "Les cadres arrondis ignorent les styles Contour réel et Texture et conservent la couleur unie du contour."
L["Texture region"] = "Région de la texture"
L["Top half"] = "Moitié supérieure"
L["True Outline"] = "Contour réel"
L["offset, size, and layer"] = "décalage, taille et calque"

L["Requires a UI reload."] = "Nécessite un rechargement de l'interface."
L["Shared entries apply to every spec."] = "Les entrées partagées s'appliquent à toutes les spécialisations."
L["down"] = "bas"
L["left"] = "gauche"
L["No target"] = "Aucune cible"
L["Out of combat and no target"] = "Hors combat et aucune cible"

L["Class Resource Text"] = "Texte des ressources de classe"
L["Click to select the value, then press Ctrl+C to copy it."] = "Cliquez pour sélectionner la valeur, puis appuyez sur Ctrl+C pour la copier."
L["HEX color"] = "Couleur HEX"
L["NSRT nickname integration"] = "Intégration des surnoms NSRT"
L["Nickname Integration"] = "Intégration des surnoms"
L["On (default): names supplied by Northern Sky Raid Tools replace character names on MSUF unit and group frames. Turn this off to always show character names in MSUF. NSRT and its settings are not modified."] = "Activé (par défaut) : les surnoms fournis par Northern Sky Raid Tools remplacent les noms de personnage sur les cadres d’unité et de groupe MSUF. Désactivez cette option pour toujours afficher les noms de personnage dans MSUF. NSRT et ses réglages ne sont pas modifiés."

-- Native 12.1 spell-ID tooltip CVar (Global > Misc > Unitframe tooltips).
L["Show spell IDs in aura tooltips"] = "Afficher les ID de sort dans les infobulles d'auras"
L["Aura tooltip spell IDs"] = "ID de sort dans les infobulles d'auras"
L["On: aura tooltips show the numeric spell ID through the game's own 12.1 option, and MSUF re-enables that option after every login because the game forgets it between sessions. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Activé : les infobulles d'auras affichent l'ID numérique du sort via l'option native 12.1 du jeu, et MSUF réactive cette option après chaque connexion car le jeu l'oublie entre les sessions. Désactivé (par défaut) : MSUF ne touche jamais à l'option du jeu, afin que d'autres addons ou un réglage console manuel gardent le contrôle ; désactiver cet interrupteur coupe l'option une seule fois."

-- Guided setup restart confirmation.
L["Run the guided setup again? The walkthrough starts over at the first step."] = "Relancer la configuration guidée ? Le parcours reprend depuis la première étape."
L["Dispel Type Colors"] = "Couleurs des types de dissipation"
L["Magic custom"] = "Magie personnalisée"
L["Magic color"] = "Couleur de la magie"
L["Curse custom"] = "Malédiction personnalisée"
L["Curse color"] = "Couleur de la malédiction"
L["Disease custom"] = "Maladie personnalisée"
L["Disease color"] = "Couleur de la maladie"
L["Poison custom"] = "Poison personnalisé"
L["Poison color"] = "Couleur du poison"
L["Bleed custom"] = "Saignement personnalisé"
L["Bleed color"] = "Couleur du saignement"
L["Optional global overrides for harmful Magic, Curse, Disease, Poison and Bleed indicators. Off uses Blizzard's current default. The last edited type is shown first in every aura preview."] = "Couleurs globales facultatives pour les indicateurs néfastes de magie, malédiction, maladie, poison et saignement. Désactivé utilise la valeur actuelle de Blizzard. Le dernier type modifié apparaît en premier dans chaque aperçu d'aura."
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Les couleurs des minuteurs et dissipations sont partagées par les auras actives d'unité et de groupe et tous les aperçus. Les couleurs de bordure et d'ombre des icônes se trouvent dans Apparence > Auras, par type d'aura."
L["Cooldown timer urgency, global Dispel types, icon borders and shadows."] = "Urgence des minuteurs, types de dissipation globaux, bordures et ombres des icônes."
L["Safe, Warning, Urgent, Magic, Curse, Disease, Poison, Bleed, icon border and icon shadow."] = "Sûr, Avertissement, Urgent, Magie, Malédiction, Maladie, Poison, Saignement, bordure et ombre d'icône."
L["While unlocked, the Combat Enter/Leave text is shown permanently as a movable handle. Drag it with the mouse or nudge it with the arrow keys. Lock it so the text only appears when entering or leaving combat."] = "Tant que la position est déverrouillée, le texte d'entrée/sortie de combat reste affiché en permanence comme poignée déplaçable. Faites-la glisser avec la souris ou déplacez-la avec les touches fléchées. Verrouillez la position pour que le texte n'apparaisse qu'en entrant ou en sortant de combat."
L["While unlocked, the Combat Timer stays visible out of combat as a movable 0:00 placeholder. Drag it with the mouse or nudge it with the arrow keys - with click-through enabled, hold ALT to drag. Lock it to freeze the position."] = "Tant que la position est déverrouillée, le minuteur de combat reste visible hors combat sous forme d'espace réservé 0:00 déplaçable. Faites-le glisser avec la souris ou déplacez-le avec les touches fléchées – si le clic à travers est activé, maintenez ALT pour le faire glisser. Verrouillez la position pour la figer."

L["Switched to profile '%s'.\n\nA UI reload is required to fully apply this profile.\n\nReload now?"] = "Basculé vers le profil « %s ».\n\nUn rechargement de l'interface est nécessaire pour appliquer entièrement ce profil.\n\nRecharger maintenant ?"
L["Switched to profile '%s'. Reload after combat with /reload."] = "Basculé vers le profil « %s ». Rechargez après le combat avec /reload."
L["Switched to profile '%s'. Reload the UI with /reload."] = "Basculé vers le profil « %s ». Rechargez l'interface avec /reload."
L["Can't reload the UI in combat. Leave combat, then type /reload."] = "Impossible de recharger l'interface en combat. Quittez le combat, puis tapez /reload."

L["Buff Reminder"] = "Rappel de buff"
L["Show placeholders for missing auras"] = "Afficher des repères pour les auras manquantes"
L["Gives every whitelisted spell its own fixed slot and draws a dimmed icon underneath it. A running aura covers its own placeholder, so a dimmed icon means that spell is missing. MSUF reads no aura data for this, so it keeps working in raids, Mythic+ and arenas. Reminder slots ignore this container's sorting and duration bars."] = "Donne à chaque sort de la liste blanche son propre emplacement fixe et dessine en dessous une icône atténuée. Une aura active recouvre son propre repère : une icône atténuée signifie donc que ce sort manque. MSUF ne lit aucune donnée d'aura pour cela, ce qui fonctionne aussi en raid, en Mythique+ et en arène. Les emplacements de rappel ignorent le tri et les barres de durée de ce conteneur."
L["Placeholder opacity"] = "Opacité du repère"
L["How strongly a missing aura's placeholder is drawn. Lower values keep the frame calm; the running aura always covers it completely either way."] = "Intensité du repère d'une aura manquante. Des valeurs faibles gardent le cadre discret ; l'aura active le recouvre de toute façon entièrement."
L["Grey out placeholders"] = "Griser les repères"
L["Draws the placeholder without colour so a missing aura reads at a glance. Turn this off to keep the spell's own colours and separate the two states by opacity or tint alone."] = "Dessine le repère sans couleur pour repérer une aura manquante d'un coup d'œil. Désactivez cette option pour conserver les couleurs du sort et distinguer les deux états uniquement par l'opacité ou la teinte."
L["Placeholder tint"] = "Teinte du repère"
L["%d fixed reminder slots · whitelist order decides their position."] = "%d emplacements de rappel fixes · l'ordre de la liste blanche définit leur position."
L["Off · this container shows only auras that are currently active."] = "Désactivé · ce conteneur n'affiche que les auras actuellement actives."
L["Reminder on"] = "Rappel activé"
L["Reminder off"] = "Rappel désactivé"
L["Click the icon to cast the spell"] = "Cliquer sur l'icône pour lancer le sort"
L["Turns every reminder slot into a cast button: clicking it casts that slot's spell at this frame's unit, whether the aura is missing or already running, so re-applying a poison or flask works. The binding is written once outside combat and never changes afterwards, so this costs no timer, no event and no aura read. Only spells work; food, flasks and other items cannot be triggered this way."] = "Transforme chaque emplacement de rappel en bouton de lancement : un clic lance le sort de cet emplacement sur l'unité de ce cadre, que l'aura manque ou soit déjà active, ce qui permet aussi de réappliquer un poison ou un flacon. La liaison est écrite une seule fois hors combat et ne change plus ensuite : ni minuteur, ni événement, ni lecture d'aura. Seuls les sorts fonctionnent ; la nourriture, les flacons et les autres objets ne peuvent pas être déclenchés ainsi."
L["Click-cast"] = "Clic-lancement"
L["Remind me about the Main Hand"] = "Me rappeler la main droite"
L["Adds a slot that watches the temporary enchant on your main hand - a weapon oil, a stone or a weapon-applied poison. Unlike an aura this state is plainly readable, so the icon lights up while the enchant runs and dims when it is gone, in every kind of content."] = "Ajoute un emplacement qui surveille l'enchantement temporaire de votre main droite : huile d'arme, pierre ou poison appliqué sur l'arme. Contrairement à une aura, cet état est directement lisible : l'icône s'allume tant que l'enchantement dure et s'estompe dès qu'il disparaît, dans tout type de contenu."
L["Remind me about the Off Hand"] = "Me rappeler la main gauche"
L["Same slot for your off hand. Both hands share the consumable configured below, which is what you normally want."] = "Le même emplacement pour votre main gauche. Les deux mains partagent le consommable configuré ci-dessous, ce qui correspond à l'usage habituel."
L["Oil or stone - item link or ID"] = "Huile ou pierre – lien d'objet ou ID"
L["Use this item"] = "Utiliser cet objet"
L["Oil or stone"] = "Huile ou pierre"
L["Paste the consumable you want the slot to offer on click. Leave it empty to keep the reminder as a pure indicator. Weapon enchants cannot be cast, so only an item makes these slots clickable."] = "Collez le consommable que l'emplacement doit proposer au clic. Laissez vide pour garder le rappel comme simple indicateur. Les enchantements d'arme ne se lancent pas : seul un objet rend ces emplacements cliquables."
L["Click uses %s."] = "Le clic utilise %s."
L["No item set · the enchant slots only indicate."] = "Aucun objet défini · les emplacements d'enchantement ne font qu'indiquer."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs. Paste an item link instead to track the buff that item applies and offer the item itself on click - flasks, runes, stones and potions all work that way. If the item's buff differs from its use effect, put both on one line: the Spell ID decides what is tracked, the item what a click uses."] = "Saisissez un ID de sort, collez un lien de sort ou tapez un nom de sort. Cette liste blanche suit des ID de sort exacts. Collez plutôt un lien d'objet pour suivre le buff que cet objet applique et proposer l'objet lui-même au clic : flacons, runes, pierres et potions fonctionnent ainsi. Si le buff de l'objet diffère de son effet d'utilisation, mettez les deux sur une ligne : l'ID de sort décide de ce qui est suivi, l'objet de ce qu'un clic utilise."
L["Click uses this item"] = "Le clic utilise cet objet"
L["Click casts this"] = "Le clic lance ce sort"
L["No click action · paste an item"] = "Aucune action au clic · collez un objet"
L["%d of %d slots can be clicked."] = "%d emplacements sur %d sont cliquables."
L["Only active auras"] = "Uniquement les auras actives"
L["Fixed slots (reminder)"] = "Emplacements fixes (rappel)"
L["Display"] = "Affichage"
L["Every whitelisted entry keeps its own place. A dimmed icon means that entry is missing."] = "Chaque entrée de la liste blanche garde sa place. Une icône atténuée signifie que cette entrée manque."
L["Only auras that are currently active are shown, packed together."] = "Seules les auras actuellement actives sont affichées, regroupées."
L["Sorting is off while this container shows fixed reminder slots · their order comes from the Whitelist."] = "Le tri est désactivé tant que ce conteneur affiche des emplacements de rappel fixes · leur ordre vient de la liste blanche."
L["Reminder slots do not draw a duration bar."] = "Les emplacements de rappel ne dessinent pas de barre de durée."
L["Unavailable"] = "Indisponible"
L["Off · switch Display to Fixed slots in Setup to use this."] = "Désactivé · passez Affichage sur Emplacements fixes dans Setup pour l'utiliser."
L["%d fixed slots · order comes from the Whitelist."] = "%d emplacements fixes · l'ordre vient de la liste blanche."
L["%d fixed slots · %d clickable · order comes from the Whitelist."] = "%d emplacements fixes · %d cliquables · l'ordre vient de la liste blanche."
L["Add a buff - Spell ID, spell link or item link"] = "Ajouter un buff – ID de sort, lien de sort ou lien d'objet"
L["Add a debuff - Spell ID, spell link or item link"] = "Ajouter un debuff – ID de sort, lien de sort ou lien d'objet"
L["Weapon enchants"] = "Enchantements d'arme"
L["Track the Main Hand enchant"] = "Suivre l'enchantement de la main droite"
L["Adds a reminder slot for the temporary enchant on your main hand - a weapon oil, a stone or a weapon-applied poison. Unlike an aura this state is plainly readable, so the icon lights up while the enchant runs and dims when it is gone, in every kind of content."] = "Ajoute un emplacement de rappel pour l'enchantement temporaire de votre main droite : huile d'arme, pierre ou poison appliqué sur l'arme. Contrairement à une aura, cet état est directement lisible : l'icône s'allume tant que l'enchantement dure et s'estompe dès qu'il disparaît, dans tout type de contenu."
L["Track the Off Hand enchant"] = "Suivre l'enchantement de la main gauche"
L["Same slot for your off hand. Both hands share the consumable set below, which is what you normally want."] = "Le même emplacement pour votre main gauche. Les deux mains partagent le consommable défini ci-dessous, ce qui correspond à l'usage habituel."
L["Bind item"] = "Lier l'objet"
L["Paste the consumable these slots should offer on click. A weapon enchant cannot be cast, so only an item makes them clickable. Leave it empty to keep them as pure indicators."] = "Collez le consommable que ces emplacements doivent proposer au clic. Un enchantement d'arme ne se lance pas : seul un objet les rend cliquables. Laissez vide pour les garder comme simples indicateurs."
L["Needs Display set to Fixed slots in Setup · enchants have no aura to show otherwise."] = "Nécessite Affichage = Emplacements fixes dans Setup · sinon les enchantements n'ont aucune aura à afficher."
L["No weapon slot tracked."] = "Aucun emplacement d'arme suivi."
L["No item bound · these slots only indicate."] = "Aucun objet lié · ces emplacements ne font qu'indiquer."
L["%d tracked"] = "%d suivis"
L["Only show what I can apply myself"] = "N'afficher que ce que je peux appliquer moi-même"
L["Hides every whitelisted spell this character cannot cast, without leaving a gap. One whitelist can then serve all your characters: the Mage keeps Arcane Intellect, the Rogue keeps the poisons. Rows with a bound item always stay, because an item is not class bound. MSUF re-checks this only when your spellbook or talents actually change, never during combat."] = "Masque chaque sort de la liste blanche que ce personnage ne peut pas lancer, sans laisser de trou. Une seule liste blanche sert alors tous vos personnages : le mage garde Intelligence des Arcanes, le voleur garde ses poisons. Les lignes avec un objet lié restent toujours, car un objet n'est pas lié à une classe. MSUF ne revérifie cela que lorsque votre grimoire ou vos talents changent réellement, jamais en combat."
L["%d hidden: not castable by this character."] = "%d masqués : ce personnage ne peut pas les lancer."
L["Always show"] = "Toujours afficher"
L["Pins this entry so the self-cast filter never hides it. Use it for anything that is not a class ability - a flask, food, a rune, a buff someone else casts on you. MSUF cannot tell those apart from another class's spell on its own: nothing reports which class owns a Spell ID."] = "Épingle cette entrée pour que le filtre ne la masque jamais. À utiliser pour tout ce qui n'est pas une capacité de classe : un flacon, de la nourriture, une rune, ou un buff qu'un autre joueur vous donne. MSUF ne peut pas les distinguer d'un sort d'une autre classe : rien n'indique à quelle classe appartient un ID de sort."
L["Filter again"] = "Refiltrer"
L["Lets the self-cast filter decide about this entry again. It will be hidden on characters that cannot cast it."] = "Redonne cette entrée au filtre. Elle sera masquée sur les personnages qui ne peuvent pas la lancer."
L["always shown"] = "toujours affiché"
L["hidden on this character"] = "masqué sur ce personnage"
L["Hides every whitelisted spell this character cannot cast, without leaving a gap. One whitelist can then serve all your characters: the Mage keeps Arcane Intellect, the Rogue keeps the poisons. Nothing reports which class owns a Spell ID, so a flask buff looks exactly like a foreign class ability here - protect those with a bound item, or with Always show on the row in the Whitelist. MSUF re-checks this only when your spellbook or talents actually change, never during combat."] = "Masque chaque sort de la liste blanche que ce personnage ne peut pas lancer, sans laisser de trou. Une seule liste blanche sert alors tous vos personnages : le mage garde Intelligence des Arcanes, le voleur garde ses poisons. Rien n'indique à quelle classe appartient un ID de sort : un buff de flacon ressemble donc exactement à un sort d'une autre classe. Protégez-les avec un objet lié ou avec Toujours afficher sur la ligne. MSUF ne revérifie cela que lorsque votre grimoire ou vos talents changent réellement, jamais en combat."

--- Arena frames (dedicated arena1-3 unit frames)
L["Arena"] = "Arène"
L["Arena Castbar"] = "Barre d'incantation d'arène"
L["Arena Frames"] = "Cadres d'arène"
L["Arena Layout"] = "Disposition d'arène"
L["Arena Opponent"] = "Adversaire d'arène"
L["Arena castbar preview"] = "Aperçu de la barre d'incantation d'arène"
L["Arena frame layout"] = "Disposition des cadres d'arène"
L["Arena spacing"] = "Espacement d'arène"
L["Aura settings are only available for Player, Target, Focus, Boss, and Arena Frames."] = "Les réglages des auras ne sont disponibles que pour les cadres Joueur, Cible, Focalisation, Boss et Arène."
L["Castbar settings are only available for Player, Target, Focus, Boss, and Arena Frames."] = "Les réglages de la barre d'incantation ne sont disponibles que pour les cadres Joueur, Cible, Focalisation, Boss et Arène."
L["MSUF Arena Frames"] = "MSUF Cadres d'arène"
L["Sort roles across entire raid"] = "Trier les rôles sur tout le raid"
L["Orders tanks, healers, and damage dealers across the whole raid instead of within each raid group. Raid and Mythic Raid only: applies to By Role together with Preserve raid groups, and to Group + Role."] = "Classe les tanks, les soigneurs et les DPS sur l'ensemble du raid au lieu de chaque groupe de raid. Raid et Raid mythique uniquement : s'applique à Par rôle avec Préserver les groupes de raid, et à Groupe + Rôle."
L["Raid-wide roles"] = "Rôles sur tout le raid"

-- Dispel border unit filter.
L["Show on"] = "Afficher sur"
L["Friendly"] = "Amical"
L["Enemy"] = "Ennemi"
L["Both"] = "Les deux"
-- Menu feature localization: resource displays, mouseover fades, markers and textures.
L[" - clear Search to reorder"] = " - videz la recherche pour réorganiser"
L[" - drag to set Custom Priority"] = " - faites glisser pour définir la priorité personnalisée"
L[" - dynamic priority active"] = " - priorité dynamique active"
L["%d tracked DoTs"] = "%d DoTs suivis"
L["85% above 15 members / 70% above 25"] = "85% au-delà de 15 membres / 70% au-delà de 25"
L["Active: %s"] = "Actif : %s"
L["Active: Always"] = "Actif : Toujours"
L["Advanced texture options"] = "Options de texture avancées"
L["All selected visibility conditions must match (AND)."] = "Toutes les conditions de visibilité sélectionnées doivent être remplies (ET)."
L["Applies the built-in additive highlight style to this texture slot."] = "Applique le style de surbrillance additif intégré à cet emplacement de texture."
L["Arms only. Shows actual aura charges in a segmented bar, using the same native display as Fury Whirlwind. These two trackers use a bar with static dividers; aura values are never read by the addon. Appearance changes during combat apply after combat."] = "Armes uniquement. Affiche les charges réelles de l'aura dans une barre segmentée, avec le même affichage natif que Tourbillon en Fureur. Ces deux suivis utilisent une barre à séparateurs fixes ; l'addon ne lit jamais les valeurs de l'aura. Les changements d'apparence effectués en combat sont appliqués après le combat."
L["Arrow"] = "Flèche"
L["Arrow direction"] = "Sens de la flèche"
L["Augmentation Evoker only. The Player power bar shows the remaining Ebon Might duration instead of Mana, and uses the Player Power settings below for width, height, position, textures and text. Essence stays an ordinary Class Resource, and Mana is available through Alternative Mana. Turn this off to get a normal Mana bar back."] = "Évocateur Augmentation uniquement. La barre de ressource du joueur affiche la durée restante de Puissance d'ébène à la place du mana. Sa largeur, sa hauteur, sa position, ses textures et son texte suivent les réglages de ressource du joueur ci-dessous. L'essence reste une ressource de classe normale et le mana est disponible via Mana alternatif. Désactivez cette option pour retrouver une barre de mana normale."
L["Aura Options, Ordering and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Auras."] = "Les options d'aura, l'ordre et le style d'aura appartiennent à ce cadre d'unité. Apparence globale de l'icône : Apparence > Auras."
L["Aura Preview Zoom"] = "Zoom d'aperçu d'aura"
L["Auto fit pips is active only for Circle, Diamond and Hex. It uses pip count x pip size plus gaps."] = "L'ajustement automatique des points fonctionne uniquement avec Cercle, Losange et Hexagone. Il utilise le nombre de points × leur taille, plus les espacements."
L["Automatic preserves the current profile behavior for the active class and specialization, including Maelstrom, Insanity, and Ebon Might hand-offs. Mana explicitly keeps Mana on the Player power bar. Vehicles always use their native resource; classes without a Mana pool keep their normal resource while the preference stays saved."] = "Automatique conserve le comportement du profil actuel pour la classe et la spécialisation actives, y compris les transitions vers Maelström, Insanité et Puissance d’ébène. Mana impose le mana sur la barre de ressource du joueur. Les véhicules utilisent toujours leur propre ressource ; les classes sans mana gardent leur ressource normale et la préférence reste enregistrée."
L["BG opacity"] = "Opacité du fond"
L["Bar height (0 = full)"] = "Hauteur de la barre (0 = pleine)"
L["Basic setup"] = "Configuration de base"
L["Below %d%% HP"] = "Sous %d%% de vie"
L["Below threshold hides this texture until the unit reaches the configured HP threshold."] = "En dessous du seuil masque cette texture jusqu'à ce que l'unité atteigne le seuil HP configuré."
L["Border and arrow"] = "Bordure et flèche"
L["Border color and opacity are in Appearance > Colors > Group Frame Colors."] = "La couleur et l'opacité de la bordure se trouvent dans Apparence > Couleurs > Couleurs du cadre de groupe."
L["Boss Number"] = "Numéro du boss"
L["Boss range update rate"] = "Fréquence de vérification de portée des boss"
L["Boss update rate"] = "Fréquence de mise à jour des boss"
L["Both sides mirror the X offset. Y moves both markers together. Drag the left marker to adjust the pair."] = "Les deux côtés reflètent le décalage X. Y déplace les deux marqueurs ensemble. Faites glisser le marqueur gauche pour ajuster la paire."
L["Both sides: < frame >"] = "Deux côtés : < cadre >"
L["Both sides: > frame <"] = "Deux côtés : > cadre <"
L["Change opacity below threshold"] = "Modifier l'opacité sous le seuil"
L["Changes only the disappearing loss glow and is shared by every frame."] = "Modifie uniquement la lueur de perte qui s’estompe ; ce réglage est partagé par tous les cadres."
L["Chunked health loss"] = "Perte de vie par segments"
L["Chunked power loss"] = "Perte de ressource par segments"
L["Class Resource Smooth Fill"] = "Remplissage fluide des ressources de classe"
L["Class Resource layer"] = "Calque des ressources de classe"
L["Class Resource shape"] = "Forme des ressources de classe"
L["Class Resource text layer"] = "Calque du texte des ressources de classe"
L["Clickable portrait"] = "Portrait cliquable"
L["Elite and rare dragon"] = "Dragon élite et rare"
L["Elite (gold)"] = "Élite (or)"
L["Rare (silver)"] = "Rare (argent)"
L["Rare elite (silver)"] = "Élite rare (argent)"
L["Boss (winged gold)"] = "Boss (or ailé)"
L["Shows the selected dragon on this unit's visible portrait. Off restores the real classification. Ends when this area closes or combat starts."] = "Affiche le dragon choisi sur le portrait visible de cette unité. Désactivé rétablit la classification réelle. Se termine en quittant cette section ou au début du combat."
L["Color above threshold"] = "Couleur au-dessus du seuil"
L["Color and opacity are in Appearance > Colors > Group Frame Colors."] = "La couleur et l'opacité se trouvent dans Apparence > Couleurs > Couleurs du cadre de groupe."
L["Color by class applies to all unit power bars. Resource colors apply when it is off. A matched background follows Health."] = "La couleur de classe s’applique à toutes les barres de ressource des unités. Si elle est désactivée, les couleurs de ressource sont utilisées. Un fond synchronisé suit la vie."
L["Colors follow the currently selected preview resource."] = "Les couleurs suivent la ressource sélectionnée dans l’aperçu."
L["Combat state"] = "État de combat"
L["Creates a simple monochrome texture on the health bar. You can then choose any bar texture and place HP text above it."] = "Crée une texture monochrome simple sur la barre de santé. Vous pouvez ensuite choisir n’importe quelle texture de barre et placer le texte HP au-dessus."
L["Current target"] = "Cible actuelle"
L["Custom priority"] = "Priorité personnalisée"
L["Custom width"] = "Largeur personnalisée"
L["Displayed resource"] = "Ressource affichée"
L["Double arrow"] = "Double flèche"
L["Drag the marker in either boss preview to position it. Boss 1 shows the selected target."] = "Faites glisser le marqueur dans l'un ou l'autre des aperçus de boss pour le positionner. Boss 1 montre la cible sélectionnée."
L["Ebon Might On Player Power"] = "Puissance d'ébène sur la barre de ressource du joueur"
L["Empty %"] = "% vide"
L["Fade in (seconds)"] = "Fondu d'apparition (secondes)"
L["Fade out (seconds)"] = "Fondu de disparition (secondes)"
L["Filled %"] = "% rempli"
L["Focus color is in Appearance > Colors > Group Frame Colors."] = "La couleur de la focalisation se règle dans Apparence > Couleurs > Couleurs du cadre de groupe."
L["Font rendering"] = "Rendu des polices"
L["For Bar, the first direction controls the fill: Right fills left-to-right; Left fills right-to-left. Up or Down remains the secondary layout direction."] = "Pour Barre, la première direction contrôle le remplissage : Droite remplit de gauche à droite ; Gauche, de droite à gauche. Haut ou Bas reste la direction secondaire de disposition."
L["Global Aura Appearance"] = "Apparence globale des auras"
L["Guardian Ironfur Tracker"] = "Suivi de Ferpoil (Gardien)"
L["HP & Visibility"] = "HP et visibilité"
L["HP color"] = "Couleur de vie"
L["HP color: Gradient"] = "Couleur HP : Dégradé"
L["HP color: Off"] = "Couleur HP : Désactivé"
L["HP color: Off; threshold still affects opacity or visibility"] = "Couleur HP : Désactivé ; le seuil affecte toujours l'opacité ou la visibilité"
L["HP shape"] = "Forme HP"
