L["Highlight"] = "Surbrillance"
L["Highlight style"] = "Style de surbrillance"
L["Hover the unit frame to reveal this text. Preview stays visible. 0 seconds = instant."] = "Survolez le cadre unitaire pour faire apparaître ce texte. L'aperçu reste visible. 0 seconde = instantané."
L["In Bear Form, replaces the empty Guardian class-resource slot with an estimated Ironfur lifetime bar. Each successful cast adds one moving marker; Ursoc's Endurance and Guardian of Elune are included."] = "En forme d'ours, remplace l'emplacement vide de ressource de Gardien par une barre de durée estimée de Ferpoil. Chaque lancement réussi ajoute un marqueur mobile ; Endurance d'Ursoc et Gardien d'Elune sont pris en compte."
L["Ironfur Cast Markers"] = "Marqueurs de lancement de Ferpoil"
L["Keep Absorbs + Prediction Visible"] = "Garder les absorptions et les soins prévus visibles"
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Auras owns only the global icon theme."] = "La mise en page, les filtres, les listes et chaque style spécifique au conteneur se règlent dans chaque cadre. Apparence > Auras ne gère que le thème d'icônes global."
L["Low HP opacity: %d%%"] = "Opacité à faible vie : %d%%"
L["Lowers this DoT in the fixed priority order."] = "Abaisse ce DoT dans l'ordre de priorité fixe."
L["Marker X offset"] = "Décalage X du marqueur"
L["Marker Y offset"] = "Décalage Y du marqueur"
L["Marker anchor"] = "Ancre de marqueur"
L["Marker layout"] = "Disposition des marqueurs"
L["Marker size"] = "Taille du marqueur"
L["Move down"] = "Descendre"
L["Move up"] = "Monter"
L["Only show on mouseover"] = "Afficher uniquement au survol de la souris"
L["Opacity below threshold"] = "Opacité sous le seuil"
L["Open Frames > Party/Raid Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Ouvrez Cadres > Cadres de groupe/raid > Auras pour les filtres d'améliorations et d'affaiblissements, les listes, la visibilité et la disposition. Pour le texte, les temps de recharge, les cumuls et les barres de durée, utilisez Apparence > Auras et sélectionnez Groupe ou Raid."
L["Open Frames > Party/Raid Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Appearance > Bars > Absorb Display."] = "Ouvrez Cadres > Cadres de groupe/raid > Disposition. Texte, Barre de ressource et Atténuation par distance sont à côté des réglages de base et de Transparence. Superposition de dissipation et Bande d'affaiblissement sont sur la page Superposition de dissipation. Les soins prévus se règlent dans Apparence > Barres > Boucliers et absorptions."
L["Opens: Frames > Party/Raid Frames > Layout"] = "Ouvre : Cadres > Cadres de groupe/raid > Disposition"
L["Opens: Frames > Party/Raid Frames > Status & Indicators"] = "Ouvre : Cadres > Cadres de groupe/raid > Statut et indicateurs"
L["Options:"] = "Options :"
L["Orb size"] = "Taille de l'orbe"
L["Ordering and individual Style are edited here. Global icon theme: Appearance > Auras."] = "L'ordre et le style individuel sont édités ici. Thème d'icônes global : Apparence > Auras."
L["Pandemic only"] = "Fenêtre Pandemic uniquement"
L["Performance warning\n\nCustom Boss update rates replace the adaptive default with continuous range checks for every visible Boss Frame. Higher values can increase CPU use during encounters.\n\nStandard keeps the performance-friendly adaptive rate."] = "Avertissement de performances\n\nLes fréquences personnalisées d'actualisation des boss remplacent la valeur adaptative par des vérifications continues de distance pour chaque cadre de boss visible. Des valeurs plus élevées peuvent augmenter l'utilisation du CPU pendant les rencontres.\n\nStandard conserve la fréquence adaptative économe en ressources."
L["Player Power layer"] = "Calque de la ressource du joueur"
L["Player Power text layer"] = "Calque du texte de ressource du joueur"
L["Power Loss Color"] = "Couleur de perte de ressource"
L["Power X"] = "Ressource X"
L["Power Y"] = "Ressource Y"
L["Power bar color by class"] = "Couleur de classe pour la barre de ressource"
L["Power loss glow"] = "Lueur de perte de ressource"
L["Power text size"] = "Taille du texte de ressource"
L["Quick setup"] = "Configuration rapide"
L["Raises this DoT in the fixed priority order."] = "Élève ce DoT dans l'ordre de priorité fixe."
L["Remove DoT"] = "Supprimer DoT"
L["Requires MapkoSkin API 2.1. Disabling restores the MSUF look; unit frames and profile colors are unchanged."] = "Nécessite MapkoSkin API 2.1. La désactivation restaure l'apparence de MSUF ; Les cadres des unités et les couleurs des profils restent inchangés."
L["Resource text"] = "Texte ressource"
L["Shape, border and shadow: Appearance > Auras > Buffs. All controls here remain Group-scope aware."] = "Forme, bordure et ombre : Apparence > Auras > Buffs. Tous les contrôles ici restent sensibles à la portée du groupe."
L["Shared Dispel type colors plus the other colors available to this card's border modes."] = "Couleurs partagées des types de dissipation et autres couleurs disponibles pour les modes de bordure de cette carte."
L["Shared by Dispel borders, overlays, symbols, and every related preview."] = "Partagé par les bordures, superpositions et symboles de dissipation, ainsi que tous les aperçus associés."
L["Show Ebon Might duration (Aug)"] = "Afficher la durée de Puissance d'ébène (Augmentation)"
L["Show Ironfur cast markers"] = "Afficher les marqueurs de lancement de Ferpoil"
L["Show Ironfur tracker (Guardian)"] = "Afficher le suivi de Ferpoil (Gardien)"
L["Show Sweeping Strikes (Arms)"] = "Afficher Attaques circulaires (Armes)"
L["Show by health"] = "Afficher selon la vie"
L["Show heal prediction"] = "Afficher la prédiction de guérison"
L["Include healing from others"] = "Inclure les soins des autres joueurs"
L["Show negative heal absorbs"] = "Afficher les absorptions de soins"
L["Show only below 100% health"] = "Afficher uniquement en dessous de 100 % de santé"
L["Show positive absorbs"] = "Afficher les absorptions de dégâts"
L["Shows one moving marker per tracked Ironfur cast. The 30 Hz motion ticker exists only while the optional tracker has active casts."] = "Affiche un marqueur mobile par lancement de Ferpoil suivi. La minuterie de mouvement à 30 Hz fonctionne uniquement tant que le suivi optionnel contient des lancements actifs."
L["Single color uses this layer's configured tint. HP gradient follows the shared low, mid and high HP colors."] = "La couleur unique utilise la teinte configurée de ce calque. Le dégradé HP suit les couleurs partagées faible, moyenne et élevée HP."
L["Single marker"] = "Marqueur unique"
L["Slug uses WoW's crisp vector font renderer. Slug supports None or normal Outline; Thick Outline and text shadow are unavailable while it is active."] = "Slug utilise le rendu vectoriel net de WoW. Slug prend en charge Aucun contour ou Contour normal ; Contour épais et Ombre du texte sont indisponibles quand il est actif."
L["Soft gradient gives the whole frame a clear, portrait-safe hover cue. Solid border keeps a crisp edge. Choose its color in Appearance > Colors > Unit Frames."] = "Un dégradé doux donne à l'ensemble du cadre un signal de survol clair et sans danger pour les portraits. La bordure unie conserve un bord net. Choisissez sa couleur dans Apparence > Couleurs > Cadres unitaires."
L["Standard keeps the adaptive 0.75 / 2 second checks. Higher values continuously check visible Boss Frames at the selected rate; 20 per second is a 50 ms interval."] = "Standard conserve les vérifications adaptatives de 0,75/2 seconde. Des valeurs plus élevées vérifient en permanence les cadres de boss visibles au rythme sélectionné ; 20 par seconde correspond à un intervalle de 50 ms."
L["Status icon controls include the Level indicator, visibility, anchor, size, and layer. Position is edited in Preview."] = "Les contrôles des icônes d'état incluent l'indicateur de niveau, la visibilité, l'ancre, la taille et le calque. La position est modifiée dans Aperçu."
L["Stops tracking this DoT."] = "Arrête de suivre ce DoT."
