L["Triple arrow"] = "Triple flèche"
L["Updates per second"] = "Mises à jour par seconde"
L["Use Appearance > Bars for highlight borders and Frames > Party/Raid Frames > Status & Indicators for role, threat, dispel, corner, and raid-marker indicators. Spell Indicators are in Frames > Party/Raid Frames > Auras."] = "Utilisez Apparence > Barres pour les bordures de surbrillance et Cadres > Cadres de groupe/raid > Statut et indicateurs pour les indicateurs de rôle, de menace, de dissipation, de coin et de marqueur de raid. Les indicateurs de sorts se trouvent dans Cadres > Cadres de groupe/raid > Auras."
L["Use global bar texture"] = "Utiliser la texture de la barre globale"
L["Uses Blizzard's native StatusBar interpolation when an active aura duration is refreshed. The countdown itself remains C-side."] = "Utilise l'interpolation native StatusBar de Blizzard lorsqu'une durée d'aura active est actualisée. Le compte à rebours lui-même reste du côté C."
L["Uses a separate texture opacity below the HP threshold. The normal Opacity from Setup remains active above it."] = "Utilise une opacité de texture distincte inférieure au seuil HP. L'opacité normale de la configuration reste active au-dessus."
L["Vertical offset"] = "Décalage vertical"
L["Warrior - Sweeping Strikes"] = "Guerrier - Attaques circulaires"
L["With HP gradient selected, choose what the texture uses after it passes the threshold."] = "Avec le dégradé HP sélectionné, choisissez ce que la texture utilise après avoir dépassé le seuil."

