L["Colors: The |cff00ff00Colors|r tab lets you customize almost everything (fonts, bars, castbars, highlights)."] = "Couleurs : l'onglet |cff00ff00Couleurs|r permet de personnaliser presque tout (polices, barres, barres d'incantation, surbrillances)."
L["Combo Points, Holy Power, Soul Shards, Chi, Essence, Runes"] = "Points de combo, Puissance sacrée, Éclats d'âme, Chi, Essence, Runes"
L["Community: If you like MSUF, share it with a friend — UI addons grow by word of mouth."] = "Communauté : si vous aimez MSUF, parlez-en autour de vous – les addons d'interface se font connaître par le bouche-à-oreille."
