L["Custom Priority packs active tracked DoTs into the configured order. Inactive entries leave no gap; when A appears after B, the display automatically changes from B to A-B."] = "La priorité personnalisée regroupe les DoT suivis actifs dans l'ordre configuré. Les entrées inactives ne laissent aucun vide ; lorsque A apparaît après B, l'affichage passe automatiquement de B à A-B."
L["Custom anchor (type name or pick visually)"] = "Point d'attache personnalisé (saisir le nom ou sélectionner visuellement)"
L["Custom border color (used when Border Style is set to Custom) and background color."] = "Couleur de bordure personnalisée (utilisée lorsque le style de bordure est réglé sur Personnalisé) et couleur d'arrière-plan."
L["Custom size"] = "Taille personnalisée"
L["Danders is a great Party/Raidframe addon and works really well with MSUF"] = "Danders est un excellent addon de cadres groupe/raid et fonctionne très bien avec MSUF"
L["During development of MSUF Unhalted, R41z0r and other great addon developers helped out!"] = "Pendant le développement de MSUF Unhalted, R41z0r et d'autres excellents développeurs d'addons ont donné un coup de main !"
L["Each class keeps its own melee range spell.\nAllows one profile across multiple characters."] = "Chaque classe conserve son propre sort de portée de mêlée.\nPermet d'utiliser un seul profil sur plusieurs personnages."
