L["Open MSUF Edit Mode, select the frame, then drag it. Use the unit page > Anchor only for exact anchor/X/Y fine-tuning."] = "Ouvrez le mode édition MSUF, sélectionnez le cadre puis faites-le glisser. N’utilisez « Point d'attache » sur la page de l’unité que pour régler précisément l’ancrage et X/Y."
L["Open that unit page and use Frame Basics for width, height, and scale. Text size is in Style > Fonts or the unit Text section."] = "Sur la page de l’unité, « Bases du cadre » règle largeur, hauteur et échelle. Taille du texte : « Style > Polices » ou la section « Texte » de l’unité."
L["Use the unit page for per-unit castbar toggles and Frames > Cast Bars for shared textures, direction, text, and interrupt options."] = "Les commutateurs de barre d'incantation propres à chaque unité sont sur sa page. Textures, direction, texte et options d’interruption communs : « Cadres > Barres d'incantation »."
L["Boss frames normally appear only during boss encounters. Enable Boss Frames and use Edit Mode or Boss Preview to test them outside combat."] = "Les cadres de boss n’apparaissent normalement que pendant les rencontres de boss. Activez « Cadres de boss » et utilisez le mode édition ou l’aperçu des boss pour les tester hors combat."
L["Open Frames > Party/Raid Frames > Layout. Size & Scaling controls frame dimensions and scaling by group size. Group Layout controls growth, columns, and group visibility."] = "Ouvrez « Cadres > Cadres de groupe/raid > Disposition ». « Taille et échelle » règle les dimensions des cadres et leur échelle selon la taille du groupe. « Disposition du groupe » règle le sens de développement, les colonnes et la visibilité des groupes."
L["Open the unit page and use Text for name/health/power text patterns, anchors, offsets, font sizes, and layering."] = "Utilisez « Texte » sur la page de l’unité pour les formats du nom, de la vie et de la ressource, les ancrages, décalages, tailles de police et calques."
L["Open Style > Colors. Bar Colors and Power Bar Colors control HP/power colors; Class Bar Colors controls class overrides."] = "Ouvrez « Style > Couleurs ». « Couleurs de barre » et « Couleurs des barres de ressource » règlent vie et ressource ; « Couleurs de la barre de classe » les couleurs de classe."
L["Style > Fonts controls shared font settings. Unit pages contain per-unit name, health, and power text position and pattern settings."] = "« Style > Polices » contient les réglages communs. Les pages d’unité règlent position et format du texte."
L["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Utilisez « Tableau de bord > Réinitialiser les positions » pour replacer les cadres. « Profils » ne sert qu’à réinitialiser, copier, importer ou remplacer un profil."
L["Open Profiles for active profile, spec auto-switching, 6.x import/export strings, and reset options."] = "Ouvrez « Profils » pour le profil actif, le changement automatique selon la spécialisation, les chaînes d’import/export 6.x et la réinitialisation."
L["Open Frames > Bars. Textures & Gradient controls shared bar textures; Frame Outline and Highlight Borders control borders."] = "Ouvrez « Cadres > Barres ». « Textures et dégradé » règle les textures ; « Contour du cadre » et « Bordures de surbrillance » les contours."
L["Absorb styling and heal prediction are in Frames > Bars > Absorb Display. Use the Party or Raid scope there for group incoming heals."] = "Absorptions et prévision des soins : « Cadres > Barres > Boucliers et absorptions ». Choisissez la portée Groupe ou Raid pour les soins entrants du groupe."
L["Open the matching unit page and check Frame Basics > Enable, Load Conditions, alpha/transparency, and range fade."] = "Ouvrez la page de l’unité et vérifiez « Bases du cadre > Activer », les conditions de chargement, la transparence et l’atténuation par distance."
L["Open Frames > Party/Raid Frames > Layout. Check enable/show behavior, player/solo visibility, layout mode, frame scaling, and anchoring."] = "Ouvrez « Cadres > Cadres de groupe/raid > Disposition ». Vérifiez activation, visibilité, disposition, échelle et ancrage."
L["Open Frames > Party/Raid Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Ouvrez « Cadres > Cadres de groupe/raid > Statut et indicateurs » pour icônes, rôle, chef, assistant, vérification de disponibilité et lueur du focus."
