L["Each icon marks a buff that a class in your group can cast but this member lacks. Thorns is checked on members with the Tank role (on everyone with Thorns only on tanks off), Arcane Intellect and Divine Spirit on mana users. Combat, encounters and PvP matches hide aura data, so the icons keep their last known state until it ends."] = "Chaque icône signale une amélioration qu'une classe de votre groupe peut lancer mais qui manque à ce membre. Épines est vérifié sur les membres ayant le rôle de tank (sur tous si « Épines uniquement sur les tanks » est désactivé), Intelligence des Arcanes et Esprit divin sur les utilisateurs de mana. Le combat, les rencontres et les matchs JcJ masquent les données d'aura : les icônes gardent leur dernier état connu jusqu'à leur fin."

