-- Group aura filter tooltips.
L["Shows MSUF's curated high-value buffs from every Party or Raid member: major defensive, healing, offensive, and support cooldowns, plus tactical states such as Shroud membership and frequent high-value cooldowns such as Shadow Dance. Uses Blizzard's native aura filtering. The exact list overrides duration filters so temporary states Blizzard reports without a duration, such as Shroud membership, remain visible."] = "Affiche les buffs de grande valeur sélectionnés par MSUF pour chaque membre du groupe ou du raid : temps de recharge majeurs défensifs, de soins, offensifs et de soutien, ainsi que des états tactiques comme la présence sous Voile de dissimulation et des temps de recharge fréquents de grande valeur comme Danse de l'ombre. Utilise le filtrage d'auras natif de Blizzard. La liste exacte prime sur les filtres de durée, afin que les états temporaires que Blizzard signale sans durée, comme la présence sous Voile de dissimulation, restent visibles."
