L["%s section"] = "Section %s"
L["Abbreviates large HP numbers, absorb included, instead of printing the full value. Available while a slot shows a number."] = "Abrège les grands nombres de PV, absorption comprise, au lieu d'afficher la valeur complète. Disponible quand un emplacement affiche un nombre."
L["Action failed"] = "Échec de l'action"
L["Add Custom Buff"] = "Ajouter un buff personnalisé"
L["Adds a shade over the filled part of health bars that darkens toward the arrows you pick. The strength slider sets how dark it gets."] = "Ajoute un ombrage sur la partie remplie des barres de vie, plus sombre vers les flèches choisies. Le curseur d'intensité règle son assombrissement."
L["Adds a shield glow at the end of the health bar when absorbs plus incoming heals cover all of the missing health."] = "Ajoute une lueur de bouclier au bout de la barre de vie quand les absorptions et les soins entrants couvrent toute la vie manquante."
L["Adds or removes a fade direction; the shade darkens toward this arrow. Directions can be combined, and one always stays on."] = "Ajoute ou retire une direction de fondu ; l'ombrage s'assombrit vers cette flèche. Les directions se combinent, et l'une d'elles reste toujours active."
L["Adds the same fading shade to power bars, with its own direction arrows and strength."] = "Ajoute le même ombrage dégradé aux barres de ressource, avec ses propres flèches de direction et sa propre intensité."
L["Adds the unit's absorb shield amount after this slot's HP value, with or without a shield icon. Shown only while a shield is active."] = "Ajoute le montant du bouclier d'absorption de l'unité après la valeur de PV de cet emplacement, avec ou sans icône de bouclier. Affiché uniquement quand un bouclier est actif."
L["Also keeps Blizzard Focus visible; /reload required."] = "Garde aussi le cadre de focalisation Blizzard visible ; /reload requis."
L["Also keeps Blizzard Target visible; /reload required."] = "Garde aussi le cadre de cible Blizzard visible ; /reload requis."
L["Aura Options, Ordering and Aura Style belong to this UnitFrame. Global icon appearance: %s."] = "Options d'aura, Tri et Style d'aura appartiennent à ce cadre d'unité. Apparence globale des icônes : %s."
L["Aura sensor enabled for Dispel. Buff and Debuff icon caps may stay at 0."] = "Détection des auras activée pour la dissipation. Les limites d'icônes de buffs et de débuffs peuvent rester à 0."
L["Aura tooltip caster names"] = "Lanceurs dans les info-bulles d'aura"
L["Aura type:"] = "Type d'aura :"
L["Automatic keeps each resource's established text, such as Current for Combo Points and Current / Maximum for Vengeance Soul Fragments. The explicit modes override only the central resource value; Rune timers, Ebon Might duration and the Ironfur stack counter keep their native formats."] = "Automatique conserve le texte habituel de chaque ressource, par exemple Actuel pour les points de combo et Actuel / Maximum pour les fragments d'âme Vengeance. Les modes explicites ne remplacent que la valeur centrale de la ressource ; les minuteurs de runes, la durée de Puissance d'ébène et le compteur de cumuls de Ferpoil gardent leurs formats natifs."
L["Background Color"] = "Couleur d’arrière-plan"
L["Background opacity changes the MSUF Forever background only; text stays fully opaque."] = "L'opacité du fond ne modifie que le fond de MSUF Forever ; le texte reste entièrement opaque."
