L["Centers the level on a dark round medallion with a gold rim on every supported WoW version."] = "Centre le niveau sur un médaillon rond sombre à bord doré, sur toutes les versions de WoW prises en charge."
L["Choose frames for a Selected unitframes export. Imports automatically use the frames included in the string."] = "Choisissez les cadres pour un export Cadres d'unité sélectionnés. Les imports utilisent automatiquement les cadres inclus dans la chaîne."
L["Choose the Health and Power shape for this frame. Use shared style follows %s."] = "Choisissez la forme des barres de vie et de ressource de ce cadre. Utiliser le style partagé suit %s."
L["Class / Reaction"] = "Classe / Réaction"
L["Class Resource Layer"] = "Calque des ressources de classe"
L["Class Resource Text Layer"] = "Calque du texte des ressources de classe"
L["Classic"] = "Classique"
L["Click casting / Clique"] = "Sorts au clic / Clique"
L["Color and opacity are in %s."] = "La couleur et l'opacité se règlent dans %s."
L["Colors the border by debuff type while the unit has a debuff that Dispel border detects. Changing it asks for a UI reload."] = "Colore la bordure selon le type de débuff quand l'unité porte un débuff détecté par la bordure de dissipation. La modification demande un rechargement de l'interface."
L["Colors the border while the unit has a buff you can purge or spellsteal. Only Target and Focus frames support it."] = "Colore la bordure quand l'unité porte un buff que vous pouvez purger ou voler. Seuls les cadres de cible et de focalisation le prennent en charge."
L["Companion"] = "Compagnon"
L["Configure target highlighting in %s."] = "Configurez la mise en évidence de la cible dans %s."
L["Continue"] = "Continuer"
L["Controls how subtle or strong the rounded corners appear. Masks, outlines, highlights, mouseover edges, power bars, enabled class resources, and enabled castbars use the same value."] = "Règle la discrétion ou la force des coins arrondis. Les masques, contours, surbrillances, bords de survol, barres de ressource, ressources de classe et barres d'incantation activées utilisent la même valeur."
L["Cooldown Anchor"] = "Ancrage du temps de recharge"
L["Cooldown Font"] = "Police du temps de recharge"
L["Cooldown Timer Colors"] = "Couleurs du minuteur de recharge"
L["Cooldown X"] = "Temps de recharge X"
L["Cooldown Y"] = "Temps de recharge Y"
L["Copy Group Settings"] = "Copier les paramètres du groupe"
L["Copy Unit Settings"] = "Copier les réglages de l'unité"
L["Copy target %s"] = "Destination de copie : %s"
L["Counts incoming heals from every healer, not only your own. Useful on group frames when several healers are active."] = "Compte les soins entrants de tous les soigneurs, pas seulement les vôtres. Utile sur les cadres de groupe quand plusieurs soigneurs sont actifs."
L["Custom icon"] = "Icône personnalisée"
L["Custom: %s"] = "Personnalisé : %s"
L["Cut direction"] = "Sens de coupe"
L["Cuts long spell names on every castbar to Max name length and marks the cut with '...'. Reserved space applies only while this is on."] = "Coupe les noms de sorts longs sur toutes les barres d'incantation à Longueur max du nom et marque la coupe par '...'. L'espace réservé ne s'applique que si cette option est active."
L["Daylight"] = "Lumière du jour"
L["Decimals below sec"] = "Décimales sous (s)"
L["Deletes all MSUF profiles and settings after confirmation. Suite profiles are kept."] = "Supprime tous les profils et réglages MSUF après confirmation. Les profils de la Suite sont conservés."
L["Deletes all Suite profiles and skin settings after confirmation. MSUF data stays intact."] = "Supprime tous les profils et réglages d'apparence de la Suite après confirmation. Les données MSUF restent intactes."
L["Dispel Border, Overlay, and Symbol need each UnitFrame's Aura sensor. Enable Buffs or Debuffs on the affected UnitFrame, or turn on its Dispel feature to enable the sensor automatically. Both icon caps may stay at 0."] = "La bordure, la superposition et le symbole de dissipation nécessitent la détection des auras de chaque cadre d'unité. Activez les améliorations ou les affaiblissements du cadre concerné, ou sa fonction de dissipation pour activer automatiquement la détection. Le nombre maximal d'icônes des deux types peut rester à 0."
L["Dispel Border, Overlay, and Symbol need this UnitFrame's Aura sensor. Enable Buffs or Debuffs, or turn on this Dispel feature to enable the sensor automatically. Set both icon caps to 0 if you want no aura icons."] = "La bordure, la superposition et le symbole de dissipation nécessitent la détection des auras de ce cadre d'unité. Activez les améliorations ou les affaiblissements, ou cette fonction de dissipation pour activer automatiquement la détection. Fixez le nombre maximal d'icônes des deux types à 0 pour ne pas afficher d'icônes d'auras."
L["Dots on Target"] = "DoT sur la cible"
L["Drain"] = "Vidage"
L["Draw order on the shared 0-30 layer scale. Raise it to draw the outline above text, icons or auras on a lower layer."] = "Ordre d'affichage sur l'échelle commune des couches de 0 à 30. Augmentez la valeur pour afficher le contour devant les textes, icônes ou auras des couches inférieures."
L["Draws absorb shields on the unit, such as Power Word: Shield, as an overlay on the health bar."] = "Affiche les boucliers d'absorption de l'unité, comme Mot de pouvoir : Bouclier, en superposition sur la barre de vie."
L["Each castbar text can override the shared castbar text color. Target text exists on Target, Focus, Boss, and Arena."] = "Chaque texte de barre d'incantation peut remplacer la couleur de texte partagée. Le texte de cible existe sur Cible, Focalisation, Boss et Arène."
L["Each text has three slots: left, center and right. The slot picked here is the one the value, Hide % sign and slot size settings edit."] = "Chaque texte a trois emplacements : gauche, centre et droite. Les réglages Valeur, Masquer le signe % et taille d'emplacement modifient l'emplacement choisi ici."
L["Edge softness"] = "Douceur des bords"
L["Effect Layer (0-30)"] = "Calque d'effet (0-30)"
L["Ember"] = "Braise"
L["Enable Swing Timer module"] = "Activer le module de minuteur de swing"
L["Enable the module, then drag the selected bars outside combat. Main Hand and Off Hand can be shown together. Positions are saved in this MSUF profile."] = "Activez le module, puis faites glisser les barres sélectionnées hors combat. Main droite et Main gauche peuvent s'afficher ensemble. Les positions sont enregistrées dans ce profil MSUF."
L["Factory reset MSUF Suite?\n\nAll Suite profiles and skin settings on this account will be deleted. MSUF settings stay intact. The UI will reload."] = "Réinitialiser MSUF Suite aux réglages d'usine ?\n\nTous les profils et réglages d'apparence de la Suite de ce compte seront supprimés. Les réglages MSUF restent intacts. L'interface sera rechargée."
L["Factory reset MSUF?\n\nAll MSUF profiles and settings on this account will be deleted. Suite profiles are kept, but the active Suite profile may follow MSUF back to Default. The UI will reload."] = "Réinitialiser MSUF aux réglages d'usine ?\n\nTous les profils et réglages MSUF de ce compte seront supprimés. Les profils de la Suite sont conservés, mais le profil actif de la Suite peut suivre MSUF et revenir à Default. L'interface sera rechargée."
L["Fill and color mode affect only the health background; foreground health coloring stays independent."] = "Les modes de remplissage et de couleur n'affectent que le fond de la vie ; la couleur de premier plan de la vie reste indépendante."
L["Fill direction"] = "Sens de remplissage"
L["Fill up"] = "Remplissage"
L["Fix positions, print help, or reset MSUF or Suite."] = "Corrigez les positions, affichez l'aide ou réinitialisez MSUF ou la Suite."
L["Flips the fill direction on the Target castbar only, so it can mirror your Player castbar when the two frames face each other."] = "Inverse le sens de remplissage de la barre d'incantation de la cible uniquement, pour qu'elle reflète celle du joueur quand les deux cadres se font face."
L["Focus"] = "Focalisation"
L["Focus color is in %s."] = "La couleur de focalisation se règle dans %s."
L["Focus interrupt tracker"] = "Suivi des interruptions de la focalisation"
L["Font"] = "Police"
L["Font outline"] = "Contour de police"
L["Font size of the slot picked in Text slots only. Slots you never resize keep the normal text size."] = "Taille de police de l'emplacement choisi dans Emplacements de texte uniquement. Les emplacements jamais redimensionnés gardent la taille de texte normale."
L["Frame Outline Color"] = "Couleur du contour du cadre"
L["Gives this scope its own text style, colors and name shortening, so Shared changes stop reaching it. The font family always stays shared."] = "Donne à cette portée son propre style de texte, ses couleurs et son raccourcissement des noms, pour que les changements de Partagé ne l'atteignent plus. La famille de police reste toujours partagée."
L["Gives this unit or group its own gradient, absorb, outline and highlight settings instead of following Shared. Turning it off keeps your custom values."] = "Donne à cette unité ou à ce groupe ses propres réglages de dégradé, d'absorption, de contour et de surbrillance au lieu de suivre Partagé. La désactivation conserve vos valeurs personnalisées."
L["Gradually brightens the bar toward white as a cast nears its end, so the last moment of a cast is easy to spot."] = "Éclaircit progressivement la barre vers le blanc à l'approche de la fin d'une incantation, pour repérer facilement son dernier instant."
L["Grid %s/%s"] = "Grille %s/%s"
L["Group frame provider"] = "Fournisseur des cadres de groupe"
L["Group threat visuals show for"] = "Menace de groupe affichée pour"
L["Grow"] = "Croissance"
L["HP value"] = "Valeur de PV"
L["Heal-Absorb / Negative Heal"] = "Absorption de soins / Soins négatifs"
L["Health gradient stops"] = "Paliers du dégradé de vie"
L["Hide in Housing"] = "Masquer dans le logis"
L["Higher numbers draw this text in front. Portrait, aura and status icon layers use the same 0-30 scale; set it above whatever covers the text."] = "Les nombres plus élevés placent ce texte devant. Les calques d'icônes de portrait, d'aura et d'état utilisent la même échelle de 0 à 30 ; placez-le au-dessus de tout ce qui recouvre le texte."
L["Highlight Priority Order"] = "Ordre de priorité des surbrillances"
L["Highlights the Boss frame of the boss you are targeting. It is shared by all boss frames, so it changes only on the Shared scope."] = "Met en évidence le cadre du boss que vous ciblez. Ce réglage est commun à tous les cadres de boss et ne se modifie donc que dans la portée Partagé."
L["How dark the health bar shade gets at its strongest edge. 0 shows no shade, 1 uses the full shade color."] = "Intensité de l'ombrage de la barre de vie à son bord le plus sombre. 0 n'affiche aucun ombrage, 1 utilise la couleur d'ombrage complète."
L["How dark the power bar shade gets at its strongest edge. 0 shows no shade, 1 uses the full shade color."] = "Intensité de l'ombrage de la barre de ressource à son bord le plus sombre. 0 n'affiche aucun ombrage, 1 utilise la couleur d'ombrage complète."
L["How far the bar jolts, in pixels. 0 turns the shake off even while Shake on interrupt is enabled."] = "Amplitude de la secousse de la barre, en pixels. 0 désactive la secousse même si Tremblement à l'interruption est actif."
L["How long an interrupted cast stays visible with the interrupt message before the bar hides. 0 hides it immediately."] = "Durée pendant laquelle une incantation interrompue reste visible avec le message d'interruption avant que la barre ne disparaisse. 0 la masque immédiatement."
L["How long the text takes to fully appear once your mouse enters the unit frame. 0 shows it instantly."] = "Temps nécessaire pour que le texte apparaisse entièrement quand la souris entre dans le cadre d'unité. 0 l'affiche instantanément."
L["How long the text takes to fully fade away after your mouse leaves the unit frame. 0 hides it instantly."] = "Temps nécessaire pour que le texte disparaisse entièrement quand la souris quitte le cadre d'unité. 0 le masque instantanément."
L["Hunted Foe"] = "Ennemi traqué"
L["Icon (follows castbar)"] = "Icône (suit la barre d'incantation)"
L["Icon Border"] = "Bordure d'icône"
L["Icon Effect"] = "Effet d'icône"
L["Icon Shadow"] = "Ombre d'icône"
L["Includes each frame's own settings, auras and castbar. Shared appearance settings stay unchanged."] = "Comprend les réglages propres à chaque cadre, ses auras et sa barre d'incantation. Les réglages d'apparence partagés restent inchangés."
L["Independent from MSUF Enable; /reload required."] = "Indépendant de l'activation de MSUF ; /reload requis."
L["Jolts a castbar sideways when the cast it shows is interrupted, so kicks are easy to notice. Applies to every castbar."] = "Secoue latéralement une barre d'incantation quand son incantation est interrompue, pour bien remarquer les interruptions. S'applique à toutes les barres d'incantation."
L["Keeps this many extra pixels free next to the spell name, on top of the room kept for the cast time, so long names stay clear of the timer."] = "Garde ce nombre de pixels libres à côté du nom du sort, en plus de l'espace réservé au temps d'incantation, pour que les noms longs n'empiètent pas sur le minuteur."
L["Keeps this text hidden until your mouse is over the unit frame. Name, HP and power text each have their own switch."] = "Garde ce texte masqué jusqu'à ce que la souris survole le cadre d'unité. Le nom, les PV et le texte de ressource ont chacun leur interrupteur."
L["Large Groups"] = "Grands groupes"
L["Left edge: lower corner"] = "Bord gauche : coin inférieur"
L["Left edge: upper corner"] = "Bord gauche : coin supérieur"
L["Lets the spark stick out above and below the bar at about twice its height. Only matters while the spark is shown."] = "Fait dépasser l'étincelle au-dessus et au-dessous de la barre, à environ deux fois sa hauteur. Utile seulement quand l'étincelle est affichée."
L["Lower %s"] = "Descendre %s"
L["MSUF (Forever Version)"] = "MSUF (version Forever)"
L["MSUF Factory Reset"] = "Réinitialisation d'usine de MSUF"
L["Main Hand"] = "Main droite"
L["Makes channeled spells fill up like normal casts. Off keeps the classic look where a channel starts full and drains."] = "Fait se remplir les sorts canalisés comme les incantations normales. Désactivé garde l'aspect classique où une canalisation démarre pleine et se vide."
L["Manual width for the detached Player power bar. Available while Width mode is Manual; dragging it releases Sync width to Class Resource, because that sync would otherwise win. Unset, the bar inherits the Player frame width."] = "Largeur manuelle de la barre de ressource du joueur détachée. Disponible quand Mode largeur est sur Manuel ; la faire glisser désactive Synchroniser la largeur avec la ressource de classe, qui l'emporterait sinon. Sans valeur, la barre reprend la largeur du cadre du joueur."
L["Mapkotwo"] = "Mapkotwo"
L["Marked Add"] = "Add marqué"
L["Maximum Health Loss Color"] = "Couleur de perte de vie maximale"
L["Menu appearance preset"] = "Préréglage d'apparence du menu"
L["Mid"] = "Milieu"
L["Mirrors the HP text: left and right slots swap sides and multi-value choices flip, so Current / Percent becomes Percent / Current."] = "Inverse le texte de PV : les emplacements gauche et droit échangent leurs côtés et les choix à plusieurs valeurs s'inversent, Actuel / Pourcentage devient Pourcentage / Actuel."
L["Modifier key"] = "Touche modificatrice"
L["Moonlit Tank"] = "Tank au clair de lune"
L["Move the group or selected slot directly in Preview."] = "Déplacez le groupe ou l'emplacement sélectionné directement dans l'aperçu."
L["Move the name directly in Preview."] = "Déplacez le nom directement dans l'aperçu."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width. In Automatic mode, Augmentation Evoker uses this bar for Ebon Might; an explicit Mana selection keeps it as Mana."] = "Sort la barre de ressource du joueur du cadre d'unité. L'ancrage la relie à la pile des ressources de classe ; Synchroniser suit uniquement la largeur de la pile. En mode automatique, l'Évocateur Augmentation utilise cette barre pour Puissance d'ébène ; un choix explicite de Mana la garde en Mana."
L["Mythic"] = "Mythique"
L["Mythic Raid frames"] = "Cadres de raid mythique"
L["Non-tanks"] = "Sauf tanks"
L["Number only"] = "Nombre seul"
L["Off (default): panels keep the Classic Glass appearance. On: panels and navigation follow your accent color. Success, warning and danger colors never change."] = "Désactivé (par défaut) : les panneaux gardent l'apparence Classic Glass. Activé : les panneaux et la navigation suivent votre couleur d'accent. Les couleurs de succès, d'avertissement et de danger ne changent jamais."
L["Off (default): the accent colors buttons, tabs and highlights while panels keep the selected look. On: panels, borders and the navigation rail follow the accent too. Success, warning and danger colors never change."] = "Désactivé (par défaut) : l'accent colore les boutons, les onglets et les surbrillances, et les panneaux gardent l'apparence choisie. Activé : les panneaux, les bordures et le rail de navigation suivent aussi l'accent. Les couleurs de succès, d'avertissement et de danger ne changent jamais."
L["Off Hand"] = "Main gauche"
L["Offline %s s"] = "Hors ligne %s s"
L["On: aura tooltips name who applied the aura, coloured by reaction or class, through the game's own 12.1.5 option, and MSUF re-enables it after every login. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Activé : les info-bulles d'aura indiquent qui a appliqué l'aura, en couleur de réaction ou de classe, via l'option 12.1.5 du jeu, que MSUF réactive à chaque connexion. Désactivé (par défaut) : MSUF ne touche jamais à l'option du jeu, donc les autres addons ou un réglage manuel en console gardent la main ; désactiver cet interrupteur efface l'option une fois."
L["On: dragging this text in Preview moves all its slots together. Off: each visible slot gets its own handle so you can place it separately."] = "Activé : faire glisser ce texte dans l'aperçu déplace tous ses emplacements ensemble. Désactivé : chaque emplacement visible a sa propre poignée pour le placer séparément."
L["Opacity %"] = "Opacité %"
L["Open Priority Frames for %s"] = "Ouvrir les cadres prioritaires pour %s"
L["Open Suite Modules"] = "Ouvrir les modules de la Suite"
L["Open a Frame"] = "Ouvrir un cadre"
L["Open search result %s"] = "Ouvrir le résultat de la recherche %s"
L["Opens the global Aura icon appearance: shape, border, shadow, colors and native Player weapon enchants. This frame's container Style stays here."] = "Ouvre l'apparence globale des icônes d'aura : forme, bordure, ombre, couleurs et enchantements d'arme natifs du joueur. Le style du conteneur de ce cadre reste ici."
L["Optional modules beyond unit frames: action bars, bags, chat, minimap and more."] = "Modules optionnels au-delà des cadres d'unité : barres d'action, sacs, discussion, minicarte et plus."
L["Ordering and individual Style are edited here. Global icon theme: %s."] = "Le tri et le style individuel se règlent ici. Thème global des icônes : %s."
L["Orders Class Resource numeric text, Rune times and the Ebon Might duration text independently from the Class Resource bar and Player Power text."] = "Définit l'ordre d'affichage des valeurs des ressources de classe, des temps des runes et de la durée de Puissance d'ébène, indépendamment de la barre de ressources de classe et du texte de ressource du joueur."
L["Orders only the normal Player Power bar. It does not control Class Resource pips or their text."] = "Définit uniquement l'ordre d'affichage de la barre normale de ressource du joueur. Ne contrôle pas les points de ressources de classe ni leur texte."
L["Orders only the normal Player Power text. The visible Essence count and Ebon Might time belong to Class Resource text."] = "Définit uniquement l'ordre d'affichage du texte normal de ressource du joueur. Le nombre d'essences et la durée de Puissance d'ébène appartiennent au texte des ressources de classe."
L["Orders the Class Resource bar and pips. Its numeric, Rune and Ebon duration text uses the separate Class Resource text layer under Appearance > Text."] = "Définit l'ordre d'affichage de la barre et des points de ressources de classe. Les valeurs, les temps des runes et la durée de Puissance d'ébène utilisent la couche distincte du texte des ressources de classe, sous Apparence > Texte."
L["Party frames"] = "Cadres de groupe"
L["Pips"] = "Points"
L["Place Spell Indicator"] = "Placer l'icône de sort"
L["Player Defensives"] = "Défensifs du joueur"
L["Player Power Layer"] = "Calque de la ressource du joueur"
L["Player Power Text Layer"] = "Calque du texte de ressource du joueur"
L["Player first"] = "Joueur en premier"
L["Positive Heal Prediction"] = "Soins entrants"
L["Power Width"] = "Largeur de la ressource"
L["Power background texture"] = "Texture de fond de la ressource"
L["Power bar texture"] = "Texture de la barre de ressource"
L["Power bars glide to new values instead of jumping; turns off Chunked power loss. Set per unit: pick a unit scope with a power bar, such as Player or Target."] = "Les barres de ressource changent de valeur progressivement au lieu de sauter ; désactive Perte de ressource par segments. Se règle par unité : choisissez une portée d'unité avec une barre de ressource, comme Joueur ou Cible."
L["Power text"] = "Texte de ressource"
