L["Power value"] = "Valeur de ressource"
L["Power width"] = "Largeur de la ressource"
L["Preset accent (default)"] = "Accent du préréglage (par défaut)"
L["Preview and drag Swing Timers"] = "Prévisualiser et déplacer les minuteurs de swing"
L["Preview layer"] = "Calque d'aperçu"
L["Print the client, game mode and Blizzard addon facts for a bug report."] = "Affiche dans la discussion le client, le mode de jeu et les infos des addons Blizzard pour un rapport de bug."
