L["Remove Custom Buff"] = "Supprimer le buff personnalisé"
L["Rendering"] = "Rendu"
L["Replaces all Blizzard swing bars while enabled, even when only one hand is selected. Disabling restores Blizzard's previous visibility."] = "Remplace toutes les barres de swing Blizzard quand il est actif, même si une seule main est sélectionnée. La désactivation rétablit la visibilité précédente de Blizzard."
L["Reset Bar Colors"] = "Réinitialiser les couleurs de barre"
L["Reset NPC Type Colors"] = "Réinitialiser les couleurs des types de PNJ"
L["Reset Unitframe Colors"] = "Réinitialiser les couleurs des cadres d'unité"
L["Reset aura colors"] = "Réinitialiser les couleurs d'aura"
L["Reset gameplay colors"] = "Réinitialiser les couleurs de jouabilité"
L["Reset gradient"] = "Réinitialiser le dégradé"
L["Resource & Textures"] = "Ressource et textures"
L["Right edge: lower corner"] = "Bord droit : coin inférieur"
L["Right edge: upper corner"] = "Bord droit : coin supérieur"
L["Role Priority Order"] = "Ordre de priorité des rôles"
L["Role icon style"] = "Style d'icône de rôle"
L["Round Level Badge"] = "Badge de niveau rond"
L["Round MSUF castbar surfaces and outlines. Blizzard castbars, spell icons, and the GCD bar are not changed."] = "Arrondit les surfaces et contours des barres d'incantation MSUF. Les barres d'incantation Blizzard, les icônes de sorts et la barre de GCD ne changent pas."
L["Round level badge"] = "Badge de niveau rond"
L["Round rectangular class resource bars. Circle, Diamond, and Hex shapes are unchanged."] = "Arrondit les barres de ressources de classe rectangulaires. Les formes Cercle, Diamant et Hexagone ne changent pas."
L["Scale %"] = "Échelle %"
L["Search for %s"] = "Rechercher %s"
L["Select at least one unitframe."] = "Sélectionnez au moins un cadre d'unité."
L["Select search result %s"] = "Sélectionner le résultat de recherche %s"
L["Selected unitframes"] = "Cadres d'unité sélectionnés"
L["Selects which side and corner of slanted Health and Power bars is cut."] = "Choisit le côté et le coin coupés des barres de vie et de ressource inclinées."
L["Shades the end of the Player castbar by your latency or spell queue window, whichever is larger, to help time your next spell. Player castbar only."] = "Ombre la fin de la barre d'incantation du joueur selon votre latence ou la fenêtre de file d'attente des sorts (la plus grande), pour mieux enchaîner le sort suivant. Barre d'incantation du joueur uniquement."
L["Shadow Alpha (%)"] = "Opacité de l'ombre (%)"
L["Shadow Size"] = "Taille de l'ombre"
L["Shadow distance"] = "Distance de l'ombre"
L["Shape, border and shadow: %s. All controls here remain Group-scope aware."] = "Forme, bordure et ombre : %s. Tous les réglages ici tiennent compte de la portée de groupe."
L["Sharp / Pixel"] = "Net / Pixel"
L["Show Duration Bar"] = "Afficher la barre de durée"
L["Show MSUF button in game menu"] = "Afficher le bouton MSUF dans le menu du jeu"
L["Show Timer Text"] = "Afficher le texte du minuteur"
L["Show Tooltip"] = "Afficher l'info-bulle"
L["Show Weapon Enchants on Player"] = "Afficher les enchantements d'armes sur le joueur"
L["Show bar title"] = "Afficher le titre de la barre"
L["Show castbar with Focus Kick icon"] = "Afficher la barre d'incantation avec l'icône Kick Focus"
L["Show caster names in aura tooltips"] = "Afficher les lanceurs dans les info-bulles d'aura"
L["Show on Arena castbars"] = "Afficher sur les barres d'incantation d'arène"
L["Show on enemy nameplates (MSUF Suite)"] = "Afficher sur les barres d'info ennemies (MSUF Suite)"
L["Show preview drag hint animation"] = "Afficher l'animation d'aide au déplacement de l'aperçu"
L["Show remaining time"] = "Afficher le temps restant"
L["Show this frame only when its unit is below full health. At full health it is transparent, even in combat or with a target. Replaces the Out of combat, No target, and Out of combat and no target rules; other hide conditions still apply. Edit Mode keeps the frame visible for editing. The transparent frame can still receive mouse clicks."] = "N'affiche ce cadre que si son unité n'a pas toute sa vie. À vie pleine, il est transparent, même en combat ou avec une cible. Remplace les règles Hors combat, Aucune cible et Hors combat et aucune cible ; les autres conditions de masquage s'appliquent toujours. Le mode édition garde le cadre visible pour l'édition. Le cadre transparent reçoit toujours les clics de souris."
L["Show unitframe tooltips"] = "Afficher les info-bulles des cadres d'unité"
L["Shows HP percent with one decimal (for example, 63.4 instead of 63) in every HP slot that shows a percent."] = "Affiche le pourcentage de PV avec une décimale (par exemple 63,4 au lieu de 63) dans chaque emplacement de PV qui affiche un pourcentage."
L["Shows a shield glow at the end of the health bar while the unit is at full health and still has an absorb shield."] = "Affiche une lueur de bouclier au bout de la barre de vie quand l'unité a toute sa vie et encore un bouclier d'absorption."
L["Shows heal absorbs, effects that soak up incoming healing before health can rise, as a bar over current health."] = "Affiche les absorptions de soins, des effets qui absorbent les soins reçus avant que la vie puisse remonter, sous forme de barre sur la vie actuelle."
L["Shows incoming heals as a bar on the health bar before they land. Only your own heals count unless Include healing from others is on."] = "Affiche les soins entrants sous forme de barre sur la barre de vie avant qu'ils n'arrivent. Seuls vos soins comptent, sauf si Inclure les soins des autres joueurs est actif."
L["Shows sample bars on the frames of the selected scope, even while this bar is turned off, so you can check its look. Cannot be turned on in combat."] = "Affiche des barres d'exemple sur les cadres de la portée sélectionnée, même si cette barre est désactivée, pour vérifier son apparence. Impossible à activer en combat."
L["Shows the aggro color on the border when the unit has threat: your frame while you hold aggro, enemies attacking you, and group members with high threat."] = "Affiche la couleur d'aggro sur la bordure quand l'unité a de la menace : votre cadre quand vous avez l'aggro, les ennemis qui vous attaquent et les membres du groupe avec une menace élevée."
L["Shows the percent as a bare number (63 instead of 63%) in the selected slot only. Available when that slot's value includes a percent."] = "Affiche le pourcentage sous forme de nombre simple (63 au lieu de 63%) dans l'emplacement sélectionné uniquement. Disponible quand la valeur de cet emplacement inclut un pourcentage."
L["Shows the remaining global cooldown in the Player castbar time text while the GCD bar runs."] = "Affiche le temps de recharge global restant dans le texte de temps de la barre d'incantation du joueur pendant que la barre de GCD défile."
L["Shows the selected cut on a Health and Power bar sample."] = "Affiche la coupe choisie sur un exemple de barres de vie et de ressource."
L["Slanted"] = "Incliné"
L["Slanted bar preview"] = "Aperçu de la barre inclinée"
L["Slug"] = "Slug"
L["Smooth"] = "Lisse"
L["Soft gradient gives the whole frame a clear, portrait-safe hover cue. Solid border keeps a crisp edge. Choose its color in %s."] = "Dégradé doux donne à tout le cadre un repère de survol net qui respecte le portrait. Bordure pleine garde un bord net. Choisissez sa couleur dans %s."
L["Some settings in this section differ from their defaults. Reset section restores them."] = "Certains réglages de cette section diffèrent des valeurs par défaut. Réinitialiser la section les rétablit."
L["Spell ID %s"] = "ID de sort %s"
L["Spell Indicator Order"] = "Ordre des icônes de sorts"
L["Spell names longer than this many characters are cut and end in '...'. Names are also trimmed to fit the free bar width, so narrow bars may show fewer."] = "Les noms de sorts plus longs que ce nombre de caractères sont coupés et finissent par '...'. Les noms sont aussi raccourcis selon la largeur libre de la barre, donc les barres étroites en montrent moins."
L["Spent power drops at once while the spent part briefly stays highlighted, then fades; turns off Smooth power bar. Set per unit, like Smooth power bar."] = "La ressource dépensée chute d'un coup tandis que la partie dépensée reste brièvement en surbrillance, puis s'estompe ; désactive Barre de puissance lisse. Réglé par unité, comme Barre de puissance lisse."
L["Stack Font"] = "Police des cumuls"
L["Stack X"] = "Cumuls X"
L["Stack Y"] = "Cumuls Y"
L["Suite Action Bars"] = "Barres d'action de la Suite"
L["Suite Cooldown Manager"] = "Gestionnaire de temps de recharge de la Suite"
L["Suite Damage Meter"] = "Compteur de dégâts de la Suite"
L["Suite Factory Reset"] = "Réinitialisation d'usine de la Suite"
L["Suite Quality of Life"] = "Confort de jeu de la Suite"
L["Suite setup unavailable"] = "Configuration de la Suite indisponible"
L["Swing Timer colors"] = "Couleurs du minuteur de swing"
L["Swing Timers (Forever)"] = "Minuteurs de swing (Forever)"
L["Symbol anchor"] = "Ancrage du symbole"
L["Symbol opacity"] = "Opacité du symbole"
L["Symbol placed between values that share one slot, like Current and Percent. Used by all slots of this text."] = "Symbole placé entre les valeurs qui partagent un emplacement, comme Actuel et Pourcentage. Utilisé par tous les emplacements de ce texte."
L["Symbol set"] = "Jeu de symboles"
L["Symbol size"] = "Taille du symbole"
L["Symbol spacing"] = "Espacement des symboles"
L["Symbol strata"] = "Strate du symbole"
L["Text Layers"] = "Calques de texte"
L["Text opacity"] = "Opacité du texte"
L["Texture comes from Bars; preview uses Player background opacity multiplied by tint opacity."] = "La texture vient de Barres ; l'aperçu multiplie l'opacité du fond du joueur par l'opacité de la teinte."
L["The typeface for all unit and group frame text; every scope shares it. Fonts other addons register through SharedMedia also appear here."] = "Police de tous les textes des cadres d'unité et de groupe ; toutes les portées la partagent. Les polices que d'autres addons enregistrent via SharedMedia apparaissent aussi ici."
L["Thick outline"] = "Contour épais"
L["Timer Anchor"] = "Ancrage du minuteur"
L["Timer Thresholds"] = "Seuils du minuteur"
L["Timer X"] = "Minuteur X"
L["Timer Y"] = "Minuteur Y"
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in %s, scoped by Aura type."] = "Les couleurs de minuteur et de dissipation sont partagées par les auras d'unité/groupe en jeu et tous les aperçus. Les couleurs de bordure et d'ombre des icônes se règlent dans %s, par type d'aura."
L["Timer font"] = "Police du minuteur"
L["Timer progression"] = "Progression du minuteur"
L["Timer text X offset"] = "Décalage X du texte du minuteur"
L["Timer text Y offset"] = "Décalage Y du texte du minuteur"
L["Timer text alignment"] = "Alignement du texte du minuteur"
L["Toggle Spell Indicator"] = "Activer/désactiver l'icône de sort"
L["Tracked spell %s"] = "Sort suivi : %s"
L["Tracked spell tile %d"] = "Case %d des sorts suivis"
L["Turns every HP text slot on this frame on or off. The health bar is not affected, and your slot setup is kept."] = "Active ou désactive tous les emplacements de texte de PV de ce cadre. La barre de vie n'est pas affectée et la configuration des emplacements est conservée."
L["Turns every power text slot on this frame on or off. The power bar is not affected, and your slot setup is kept."] = "Active ou désactive tous les emplacements de texte de ressource de ce cadre. La barre de ressource n'est pas affectée et la configuration des emplacements est conservée."
L["Turns off custom font settings on every unit and group scope at once, so they all follow Shared again."] = "Désactive en une fois les réglages de police personnalisés de toutes les portées d'unité et de groupe, pour qu'elles suivent à nouveau Partagé."
L["Turns off custom settings on every unit and group scope at once, so all frames follow Shared again. Their custom values stay saved."] = "Désactive en une fois les réglages personnalisés de toutes les portées d'unité et de groupe, pour que tous les cadres suivent à nouveau Partagé. Leurs valeurs personnalisées restent enregistrées."
L["Turns this frame's name text on or off. Its anchor, size and color stay saved while it is off."] = "Active ou désactive le texte du nom de ce cadre. Son ancrage, sa taille et sa couleur restent enregistrés quand il est désactivé."
L["Unavailable fill color"] = "Couleur si interruption indisponible"
L["Updates the Player power text on every power tick instead of the regular update rate. Only the Player frame uses it; set it on the Shared scope."] = "Met à jour le texte de ressource du joueur à chaque tick de ressource au lieu de la fréquence normale. Seul le cadre du joueur l'utilise ; réglez-le dans la portée Partagé."
L["Use MapkoSkin for MSUF menus"] = "Utiliser MapkoSkin pour les menus MSUF"
L["Use NSRT nicknames on MSUF frames"] = "Utiliser les surnoms NSRT sur les cadres MSUF"
L["Use Preview and drag Swing Timers to see textures without attacking."] = "Utilisez l'aperçu et déplacez les minuteurs de swing pour voir les textures sans attaquer."
L["Use bar background texture"] = "Utiliser la texture de fond de barre"
L["Use bar texture"] = "Utiliser la texture de barre"
L["Voidcaller"] = "Appeleur du Vide"
L["What the selected slot shows. None leaves the slot empty; choices with several values are joined by the Delimiter."] = "Ce qu'affiche l'emplacement sélectionné. Aucun laisse l'emplacement vide ; les choix à plusieurs valeurs sont joints par le délimiteur."
L["When anchored here, Player power settings are managed by Class Resources. In Automatic mode, Augmentation Evoker shows Ebon Might on this bar."] = "Quand elle est ancrée ici, les réglages de ressource du joueur sont gérés par Ressources de classe. En mode automatique, l'Évocateur Augmentation affiche Puissance d'ébène sur cette barre."
L["When several highlight borders show at once, the highest one in the list wins. Turn this on to reorder the list by dragging."] = "Quand plusieurs bordures de surbrillance s'affichent en même temps, la plus haute de la liste l'emporte. Activez cette option pour réordonner la liste par glisser-déposer."
L["Where the name is pinned on the frame and how it aligns. Dragging it in Preview offsets it from this point."] = "Où le nom est fixé sur le cadre et comment il s'aligne. Le faire glisser dans l'aperçu le décale à partir de ce point."
L["Which way the bar grows during a cast, on every castbar. Channels drain the other way unless Always use fill direction for all casts is on."] = "Sens de progression de la barre pendant une incantation, sur toutes les barres d'incantation. Les canalisations se vident dans l'autre sens, sauf si Toujours utiliser la direction de remplissage pour tous les sorts est actif."
L["Width in pixels of the normal frame outline; 0 hides it. Aggro, dispel and other highlight borders use their own thickness."] = "Largeur en pixels du contour normal du cadre ; 0 le masque. Les bordures d'aggro, de dissipation et autres surbrillances ont leur propre épaisseur."
L["Width of the border around each castbar, in pixels; 0 removes it. The Interrupt Ready border style colors this border, so keep it above 0 for that style."] = "Largeur de la bordure de chaque barre d'incantation, en pixels ; 0 la supprime. Le style de bordure Interruption prête colore cette bordure, gardez-la donc au-dessus de 0 pour ce style."
L["Window %d"] = "Fenêtre %d"
L["Writes the instant spell's name on the GCD bar and shows its icon. Off leaves the spell text blank."] = "Écrit le nom du sort instantané sur la barre de GCD et affiche son icône. Désactivé laisse le texte du sort vide."
L["not installed"] = "non installé"
L["only the global %s icon shape, border and shadow settings, plus the shared Blizzard Buff/Debuff visibility settings; other Aura types and all Unit/Group lane settings stay unchanged"] = "uniquement les réglages globaux de forme, de bordure et d'ombre des icônes %s, plus les réglages partagés de visibilité des buffs/débuffs Blizzard ; les autres types d'aura et tous les réglages de lignes d'unité/groupe restent inchangés"
L["only the global %s icon shape, border and shadow settings; other Aura types and all Unit/Group lane settings stay unchanged"] = "uniquement les réglages globaux de forme, de bordure et d'ombre des icônes %s ; les autres types d'aura et tous les réglages de lignes d'unité/groupe restent inchangés"
L["preview element"] = "élément d'aperçu"

